## 2️⃣ CREATE VOICE MEETINGS SECTION COMPONENT

```vue src/components/layout/VoiceMeetingsSection.vue
<script setup>
import NavItem from './NavItem.vue'
</script>

<template>
  <div 
    v-if="!isCollapsed || isMobile"
    class="px-2 py-3 shrink-0 border-b border-base-content/5"
  >
    <!-- Section Header -->
    <button
      v-if="!isCollapsed || isMobile"
      class="flex items-center justify-between w-full px-3 py-2 text-xs font-semibold text-base-content/60 hover:text-base-content/80 transition-colors"
      @click.stop="voiceMeetingsExpanded = !voiceMeetingsExpanded"
      title="Toggle Voice Meetings"
    >
      <span class="flex items-center gap-2">
        <i class="fas fa-phone text-xs"></i>
        VOICE CALLS
      </span>
      <i 
        :class="voiceMeetingsExpanded ? 'fa-solid fa-chevron-up' : 'fa-solid fa-chevron-down'" 
        class="text-xs"
      ></i>
    </button>

    <!-- Content Area -->
    <div v-if="voiceMeetingsExpanded || isCollapsed" class="flex flex-col gap-2 mt-2">

      <!-- Active Calls Display -->
      <div v-if="activeCallCount > 0" class="space-y-2">
        <div class="text-[10px] font-semibold uppercase text-base-content/40 px-3">
          {{ activeCallCount }} Active {{ activeCallCount === 1 ? 'Call' : 'Calls' }}
        </div>

        <div 
          v-for="call in allActiveCalls" 
          :key="call.id"
          class="flex items-center gap-2 px-3 py-2 rounded-lg bg-success/10 border border-success/30 text-xs"
        >
          <div class="flex-1 min-w-0">
            <div class="font-semibold text-success truncate">
              {{ formatCallParticipants(call.participants) }}
            </div>
            <div class="text-base-content/60">{{ formatDuration(call.duration) }}</div>
          </div>
          <button
            @click.stop="handleEndCall(call.id)"
            class="btn btn-xs btn-ghost text-error hover:text-error hover:bg-error/20"
            title="End call"
          >
            <i class="fas fa-phone-slash text-xs"></i>
          </button>
        </div>
      </div>

      <!-- Online Members -->
      <div v-if="onlineMembers.length > 0" class="space-y-2">
        <div class="text-[10px] font-semibold uppercase text-base-content/40 px-3">
          {{ onlineMembers.length }} Online
        </div>

        <div class="flex flex-col gap-1">
          <button
            v-for="member in onlineMembers"
            :key="member.username"
            @click.stop="handleCallMember(member)"
            class="flex items-center gap-2 px-3 py-2 rounded-lg hover:bg-white/8 transition-colors text-sm text-base-content/80"
            :title="`Call ${member.username}`"
          >
            <!-- Avatar with Online Indicator -->
            <div class="relative shrink-0">
              <img 
                :src="member.avatar" 
                :alt="member.username"
                class="w-6 h-6 rounded-full"
              />
              <div class="absolute bottom-0 right-0 w-2 h-2 bg-success rounded-full"></div>
            </div>

            <!-- Member Info -->
            <div v-if="!isCollapsed" class="flex-1 min-w-0">
              <div class="text-xs font-semibold truncate">{{ member.username }}</div>
            </div>

            <!-- Call Button -->
            <button
              @click.stop="handleCallMember(member)"
              class="btn btn-xs btn-ghost p-1 text-primary hover:text-primary hover:bg-primary/20"
              title="Call member"
            >
              <i class="fas fa-phone text-xs"></i>
            </button>
          </button>
        </div>
      </div>

      <!-- No Members State -->
      <div v-else class="text-center py-4 text-base-content/40 text-xs">
        <i class="fas fa-users text-lg block mb-1"></i>
        <span>No members online</span>
      </div>

      <!-- Call History -->
      <div v-if="callHistory.length > 0 && !isCollapsed" class="border-t border-base-content/5 pt-2 mt-2">
        <div class="text-[10px] font-semibold uppercase text-base-content/40 px-3 mb-2">
          Recent Calls
        </div>

        <div class="flex flex-col gap-1 max-h-32 overflow-y-auto">
          <div
            v-for="call in callHistory.slice(0, 3)"
            :key="call.id"
            class="text-[10px] px-3 py-1.5 rounded bg-base-content/5 text-base-content/70"
          >
            <div class="truncate font-semibold">{{ formatCallParticipants(call.participants) }}</div>
            <div class="text-[9px] text-base-content/50">{{ formatHistoryTime(call.endedAt) }}</div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'VoiceMeetingsSection',
  props: {
    isCollapsed: { type: Boolean, default: false },
    isMobile: { type: Boolean, default: false }
  },
  emits: ['call-initiated', 'call-ended'],
  data() {
    return {
      voiceMeetingsExpanded: true,
      callDurationTimer: null
    }
  },
  computed: {
    allActiveCalls() {
      return this.$storex.calls.allActiveCalls
    },
    activeCallCount() {
      return this.$storex.calls.activeCallCount
    },
    onlineMembers() {
      const currentUser = this.$storex.users.user
      const onlineUsers = this.$storex.users.onlineUsers || {}

      return Object.values(onlineUsers)
        .filter(user => user.username !== currentUser?.username)
        .slice(0, 10) // Show top 10 online members
    },
    callHistory() {
      return this.$storex.calls.callHistory
    }
  },
  mounted() {
    // Update call durations every second
    this.callDurationTimer = setInterval(() => {
      this.allActiveCalls.forEach(call => {
        const duration = Math.floor((Date.now() - call.startedAt) / 1000)
        this.$storex.calls.updateDuration({ callId: call.id, duration })
      })
    }, 1000)
  },
  beforeUnmount() {
    if (this.callDurationTimer) {
      clearInterval(this.callDurationTimer)
    }
  },
  methods: {
    async handleCallMember(member) {
      try {
        const callId = await this.$storex.calls.initiateCall({
          targetUserId: member.username,
          targetUserName: member.username,
          targetUserAvatar: member.avatar
        })
        this.$emit('call-initiated', callId)
      } catch (error) {
        console.error('Failed to initiate call:', error)
        this.$storex.session.onError('Failed to initiate call')
      }
    },
    async handleEndCall(callId) {
      try {
        await this.$storex.calls.endCall(callId)
        this.$emit('call-ended', callId)
      } catch (error) {
        console.error('Failed to end call:', error)
        this.$storex.session.onError('Failed to end call')
      }
    },
    formatCallParticipants(participants) {
      if (!participants || participants.length === 0) return 'Unknown'
      if (participants.length === 1) return participants[0]
      if (participants.length === 2) return participants.join(' & ')
      return `${participants[0]} +${participants.length - 1}`
    },
    formatDuration(seconds) {
      if (!seconds) return '0s'
      if (seconds < 60) return `${seconds}s`
      const minutes = Math.floor(seconds / 60)
      const secs = seconds % 60
      return `${minutes}m ${secs}s`
    },
    formatHistoryTime(timestamp) {
      if (!timestamp) return ''
      const date = new Date(timestamp)
      const now = new Date()
      const diffMs = now - date
      const diffMins = Math.floor(diffMs / 60000)

      if (diffMins < 60) return `${diffMins}m ago`
      const diffHours = Math.floor(diffMins / 60)
      if (diffHours < 24) return `${diffHours}h ago`
      return date.toLocaleDateString()
    }
  }
}
</script>
