  props: {
    call: { type: Object, default: null },
    autoExpireSeconds: { type: Number, default: 30 }
  },
  emits: ['accept', 'reject'],
  data() {
    return {
      callTimeRemaining: 30,
      expiryTimer: null
    }
  },
  computed: {
    incomingCall() {
      return this.call
    }
  },
  watch: {
    call(newVal) {
      if (newVal) {
        this.callTimeRemaining = this.autoExpireSeconds
        this.startExpiryTimer()
      } else {
        this.clearExpiryTimer()
      }
    }
  },
  methods: {
    startExpiryTimer() {
      this.expiryTimer = setInterval(() => {
        this.callTimeRemaining--
        if (this.callTimeRemaining <= 0) {
          this.handleRejectCall()
        }
      }, 1000)
    },
    clearExpiryTimer() {
      if (this.expiryTimer) {
        clearInterval(this.expiryTimer)
        this.expiryTimer = null
      }
    },
    handleAcceptCall() {
      this.$emit('accept', this.incomingCall.id)
      this.clearExpiryTimer()
    },
    handleRejectCall() {
      this.$emit('reject', this.incomingCall.id)
      this.clearExpiryTimer()
    }
  },
  beforeUnmount() {
    this.clearExpiryTimer()
  }
}
</script>

