import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

export const namespaced = true

export const state = () => ({
  // Active call sessions
  activeCalls: {}, // { callId: { id, initiator, participants, startedAt, duration, status } }

  // Incoming call notifications
  incomingCalls: {}, // { callId: { id, from, timestamp, status } }

  // Call history
  callHistory: [], // [{ id, participants, startedAt, endedAt, duration, status }]

  // Current user's call state
  currentCallId: null,
  callStatus: 'idle', // 'idle' | 'ringing' | 'connecting' | 'active' | 'ending'

  // Internal test mode (for development/UI testing)
  _testMode: false,
  _testModeTimer: null,
  _dummyUsers: ['alice', 'bob', 'charlie', 'diana', 'eva']
})

export const getters = getterTree(state, {
  // Get all active calls
  allActiveCalls: (state) => Object.values(state.activeCalls),

  // Get current call details
  currentCall: (state) => state.currentCallId ? state.activeCalls[state.currentCallId] : null,

  // Get all incoming calls
  allIncomingCalls: (state) => Object.values(state.incomingCalls),

  // Check if user is in a call
  isInCall: (state) => state.currentCallId !== null && state.callStatus === 'active',

  // Get call history
  recentCallHistory: (state) => state.callHistory.slice(-10),

  // Get active call count
  activeCallCount: (_, getters) => getters.allActiveCalls.length,

  // Get incoming call count
  incomingCallCount: (_, getters) => getters.allIncomingCalls.length
})

export const mutations = mutationTree(state, {
  // Initialize a new active call
  addActiveCall(state, call) {
    state.activeCalls[call.id] = {
      id: call.id,
      chatId: call.chatId,
      initiator: call.initiator,
      participants: call.participants || [call.initiator],
      startedAt: call.startedAt || new Date().getTime(),
      duration: 0,
      status: call.status || 'connecting'
    }
  },

  // Update active call status
  updateCallStatus(state, { callId, status }) {
    if (state.activeCalls[callId]) {
      state.activeCalls[callId].status = status
    }
  },

  // Update call duration (runs every second)
  updateCallDuration(state, { callId, duration }) {
    if (state.activeCalls[callId]) {
      state.activeCalls[callId].duration = duration
    }
  },

  // Add participant to active call
  addParticipantToCall(state, { callId, userId }) {
    if (state.activeCalls[callId] && !state.activeCalls[callId].participants.includes(userId)) {
      state.activeCalls[callId].participants.push(userId)
    }
  },

  // Remove participant from active call
  removeParticipantFromCall(state, { callId, userId }) {
    if (state.activeCalls[callId]) {
      state.activeCalls[callId].participants = state.activeCalls[callId].participants.filter(p => p !== userId)
    }
  },

  // End an active call
  endActiveCall(state, callId) {
    const call = state.activeCalls[callId]
    if (call) {
      // Move to history
      state.callHistory.push({
        ...call,
        endedAt: new Date().getTime(),
        status: 'ended'
      })
      // Remove from active
      delete state.activeCalls[callId]
      if (state.currentCallId === callId) {
        state.currentCallId = null
        state.callStatus = 'idle'
      }
    }
  },

  // Add incoming call notification
  addIncomingCall(state, incomingCall) {
    state.incomingCalls[incomingCall.id] = {
      id: incomingCall.id,
      from: incomingCall.from,
      fromName: incomingCall.fromName,
      fromAvatar: incomingCall.fromAvatar,
      timestamp: new Date().getTime(),
      status: 'pending'
    }
  },

  // Remove incoming call notification
  removeIncomingCall(state, callId) {
    delete state.incomingCalls[callId]
  },

  // Set current call
  setCurrentCall(state, callId) {
    state.currentCallId = callId
  },

  // Set call status
  setCallStatus(state, status) {
    state.callStatus = status
  },

  // Set test mode
  setTestMode(state, enabled) {
    state._testMode = enabled
  },

  // Set test mode timer
  setTestModeTimer(state, timer) {
    state._testModeTimer = timer
  },

  // Clear all call state (for logout/reset)
  clearAllCalls(state) {
    state.activeCalls = {}
    state.incomingCalls = {}
    state.currentCallId = null
    state.callStatus = 'idle'
    if (state._testModeTimer) {
      clearInterval(state._testModeTimer)
      state._testModeTimer = null
    }
    state._testMode = false
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    /**
     * Initiate a new voice call with a target user or chat
     * Uses chat.id as the call identifier for integration with chat system
     */
    async initiateCall({ state, commit }, { chatId, targetUserId, targetUserName, targetUserAvatar }) {
      // Use chatId as the call ID for seamless chat integration
      const callId = chatId || `call_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
      const currentUser = $storex.users.user

      // Add to active calls
      commit('addActiveCall', {
        id: callId,
        chatId,
        initiator: currentUser.username,
        participants: [currentUser.username, targetUserId]
      })

      commit('setCurrentCall', callId)
      commit('setCallStatus', 'ringing')

      // Emit socket event to initiate call
      $storex.session.emit({
        event: 'voice-call-initiate',
        data: {
          callId,
          chatId,
          from: currentUser.username,
          fromName: currentUser.username,
          fromAvatar: currentUser.avatar,
          to: targetUserId,
          timestamp: new Date().getTime()
        }
      })

      // Start test mode duration if enabled
      if (state._testMode) {
        setTimeout(() => {
          $storex.calls.startCallDuration(callId)
        }, 1500)
      }

      return callId
    },

    /**
     * Handle incoming call notification
     */
    handleIncomingCall({ commit }, incomingCall) {
      commit('addIncomingCall', incomingCall)
    },

    /**
     * Accept incoming call
     */
    async acceptCall({ state, commit }, callId) {
      const incomingCall = state.incomingCalls[callId]
      if (!incomingCall) return

      const currentUser = $storex.users.user

      // Create active call
      commit('addActiveCall', {
        id: callId,
        initiator: incomingCall.from,
        participants: [incomingCall.from, currentUser.username]
      })

      commit('setCurrentCall', callId)
      commit('setCallStatus', 'connecting')
      commit('removeIncomingCall', callId)

      // Emit socket event
      $storex.session.emit({
        event: 'voice-call-accept',
        data: {
          callId,
          acceptedBy: currentUser.username,
          timestamp: new Date().getTime()
        }
      })

      // Start test mode duration if enabled
      if (state._testMode) {
        setTimeout(() => {
          $storex.calls.startCallDuration(callId)
        }, 1500)
      }
    },

    /**
     * Reject incoming call
     */
    async rejectCall({ state, commit }, callId) {
      const incomingCall = state.incomingCalls[callId]
      if (!incomingCall) return

      const currentUser = $storex.users.user
      commit('removeIncomingCall', callId)

      // Emit socket event
      $storex.session.emit({
        event: 'voice-call-reject',
        data: {
          callId,
          rejectedBy: currentUser.username,
          timestamp: new Date().getTime()
        }
      })
    },

    /**
     * End active call
     */
    async endCall({ state, commit }, callId) {
      const currentUser = $storex.users.user

      commit('endActiveCall', callId)
      commit('setCallStatus', 'idle')

      // Emit socket event
      $storex.session.emit({
        event: 'voice-call-end',
        data: {
          callId,
          endedBy: currentUser.username,
          timestamp: new Date().getTime()
        }
      })
    },

    /**
     * Add participant to call (for multi-user calls)
     */
    addParticipant({ state, commit }, { callId, userId }) {
      commit('addParticipantToCall', { callId, userId })

      // Notify other participants
      $storex.session.emit({
        event: 'voice-call-participant-added',
        data: {
          callId,
          userId,
          timestamp: new Date().getTime()
        }
      })
    },

    /**
     * Update call duration (called by timer)
     */
    updateDuration({ commit }, { callId, duration }) {
      commit('updateCallDuration', { callId, duration })
    },

    /**
     * Enable test mode for UI development
     * Automatically simulates realistic call lifecycle without real voice infrastructure
     */
    enableTestMode({ commit }, enabled = true) {
      commit('setTestMode', enabled)
      if (!enabled) {
        $storex.calls.stopCallDuration()
      }
    },

    /**
     * Start automatic call duration updates (test mode)
     * Simulates realistic call progression: connecting → active → participant additions → auto-end
     */
    startCallDuration({ state, commit }, callId) {
      if (!state._testMode || !state.activeCalls[callId]) return

      const call = state.activeCalls[callId]
      let phase = 0
      const phases = [
        // Phase 0: Connecting (2 seconds)
        { duration: 2000, action: () => {
          if (call.status !== 'connecting') commit('updateCallStatus', { callId, status: 'connecting' })
        }},
        // Phase 1: Active (1 second in, then transition)
        { duration: 1000, action: () => {
          if (call.status !== 'active') commit('updateCallStatus', { callId, status: 'active' })
        }},
        // Phase 2: Auto-add participant at 10 seconds
        { duration: 9000, action: () => {
          if (call.participants.length < 3) {
            const randomUser = state._dummyUsers[Math.floor(Math.random() * state._dummyUsers.length)]
            if (!call.participants.includes(randomUser)) {
              commit('addParticipantToCall', { callId, userId: randomUser })
            }
          }
        }},
        // Phase 3: Auto-end call at 30 seconds
        { duration: 20000, action: () => {
          commit('endActiveCall', callId)
          commit('setCallStatus', 'idle')
        }}
      ]

      let currentPhase = 0
      let elapsed = 0

      const tickInterval = setInterval(() => {
        if (!state.activeCalls[callId]) {
          clearInterval(tickInterval)
          return
        }

        elapsed += 1000
        const duration = Math.floor(elapsed / 1000)
        commit('updateCallDuration', { callId, duration })

        // Execute phase actions
        if (currentPhase < phases.length) {
          if (elapsed >= phases.slice(0, currentPhase + 1).reduce((sum, p) => sum + p.duration, 0)) {
            if (currentPhase < phases.length - 1) {
              phases[currentPhase].action()
              currentPhase++
            } else {
              phases[currentPhase].action()
              clearInterval(tickInterval)
            }
          }
        }
      }, 1000)

      commit('setTestModeTimer', tickInterval)
    },

    /**
     * Stop call duration timer
     */
    stopCallDuration({ state, commit }) {
      if (state._testModeTimer) {
        clearInterval(state._testModeTimer)
        commit('setTestModeTimer', null)
      }
    },

    /**
     * Create a test incoming call for UI development
     * Simulates receiving a call from a random or specified user
     */
    createTestIncomingCall({ commit }, options = {}) {
      const callId = `call_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
      const dummyUsers = ['alice', 'bob', 'charlie', 'diana', 'eva']
      const randomUser = dummyUsers[Math.floor(Math.random() * dummyUsers.length)]

      const incomingCall = {
        id: callId,
        from: options.from || randomUser,
        fromName: options.fromName || randomUser.charAt(0).toUpperCase() + randomUser.slice(1),
        fromAvatar: options.fromAvatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${randomUser}`,
        timestamp: new Date().getTime()
      }

      commit('addIncomingCall', incomingCall)

      // Auto-reject after 30 seconds if not answered
      setTimeout(() => {
        if (state.incomingCalls[callId]) {
          commit('removeIncomingCall', callId)
        }
      }, 30000)

      return callId
    },

    /**
     * Clear all calls on logout
     */
    clearCalls({ commit }) {
      commit('clearAllCalls')
    }
  }
)

