          :disabled="selectedMembers.length === 0"
          class="flex-1 px-4 py-2 bg-success hover:bg-success/90 disabled:bg-success/50 disabled:cursor-not-allowed rounded-lg text-white text-sm font-medium transition-all active:scale-95"
        >
          <i class="fa-solid fa-phone mr-2"></i>
          Start Call
        </button>
      </div>
