import ChatImageCarousel from './ChatImageCarousel.vue'

export default {
  components: {
    ChatImageCarousel,
    ChatLLMModelSelector,
    ChatProfileSelector,
    FileExplorerPanel,
    VoiceCallModal
  },
  props: {
    waiting: Boolean,
    isEditing: Boolean,
    isVoiceSession: Boolean,
    searching: Boolean,
    readOnly: Boolean,
    selectedModel: String,
    aiModels: { type: Array, default: () => [] },
    images: { type: Array, default: () => [] },
    voiceLanguageLabel: String,
    profiles: { type: Array, default: () => [] },
    selectedProfiles: { type: Array, default: () => [] },
    chat: { type: Object, required: true }
  },
  emits: [
    'send', 'cancel-edit', 'model-changed',
    'toggle-voice', 'remove-image', 'preview-image', 'profiles-selected',
    'file-selected', 'voice-call-initiated'
  ],
  data() {
    return {
      showFileModal: false,
      showVoiceCallModal: false,
      callStateTimer: null
    }
  },
  computed: {
    projectRootPath() {
      return this.$project?.abs_project_path || '/'
    },
    onlineMembers() {
      const currentUser = this.$storex.users.user
      const onlineUsers = this.$storex.users.onlineUsers || {}

      return Object.values(onlineUsers)
        .filter(user => user.username !== currentUser?.username)
        .slice(0, 10)
    },
    activeCall() {
      return this.$storex.calls?.currentCall || null
    },
    isActiveCallForThisChat() {
      return this.activeCall && this.chat?.id && this.activeCall.chatId === this.chat.id
    },
    callButtonTooltip() {
      if (this.isActiveCallForThisChat) {
        return `Call in progress • ${this.formatDuration(this.activeCall.duration)}`
      }
      return 'Start voice call'
    }
  },
  watch: {
    activeCall() {
      this.$forceUpdate()
    }
  },
  mounted() {
    this.callStateTimer = setInterval(() => {
      if (this.isActiveCallForThisChat) {
        this.$forceUpdate()
      }
    }, 1000)
  },
  beforeUnmount() {
    if (this.callStateTimer) {
      clearInterval(this.callStateTimer)
    }
  },
  methods: {
    formatDuration(seconds) {
      if (!seconds) return '00:00'
      const hours = Math.floor(seconds / 3600)
      const minutes = Math.floor((seconds % 3600) / 60)
      const secs = seconds % 60
      if (hours > 0) {
        return `${hours}:${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`
      }
      return `${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`
    },
    async handleCallButtonClick() {
      if (this.isActiveCallForThisChat) {
        await this.handleEndCall()
      } else {
        this.openVoiceCallModal()
      }
    },
    async handleEndCall() {
      if (!this.activeCall?.chatId) return
      try {
        await this.$storex.calls.endCall(this.activeCall.chatId)
        this.$storex.session.onInfo('Call ended')
      } catch (error) {
        console.error('Failed to end call:', error)
        this.$storex.session.onError('Failed to end call')
      }
    },
    openFileModal() {
      this.showFileModal = true
    },
    closeFileModal() {
      this.showFileModal = false
    },
    onFileSelected(fileData) {
      this.$emit('file-selected', fileData.path)
      this.closeFileModal()
    },
    openVoiceCallModal() {
      this.showVoiceCallModal = true
    },
    closeVoiceCallModal() {
      this.showVoiceCallModal = false
    },
    async handleInitiateCall(callData) {
      try {
        const chatId = await this.$storex.calls.initiateCall({
          chatId: callData.chatId,
          targetUserId: callData.participants[1],
          targetUserName: callData.participants[1],
          targetUserAvatar: this.onlineMembers.find(m => m.username === callData.participants[1])?.avatar
        })

        this.$emit('voice-call-initiated', {
          chatId,
          participants: callData.participants
        })

        this.$storex.session.onInfo(`Voice call initiated with ${callData.participants.slice(1).join(', ')}`)
      } catch (error) {
        console.error('Failed to initiate call:', error)
        this.$storex.session.onError('Failed to initiate voice call')
      }
    }
  }
}
