<script>
export default {
  props: {
    show: { type: Boolean, default: false },
    chat: { type: Object, required: true },
    onlineMembers: { type: Array, default: () => [] }
  },
  emits: ['close', 'initiate-call'],
  data() {
    return {
      selectedMembers: []
    }
  },
  computed: {
    currentUser() {
      return this.$storex.users.user?.username || 'You'
    },
    participantCount() {
      return this.selectedMembers.length + 1
    },
    availableMembers() {
      const currentUsername = this.currentUser
      return (this.onlineMembers || []).filter(m => m.username !== currentUsername)
    },
    isGroupCall() {
      return this.selectedMembers.length > 1
    }
  },
  watch: {
    show(newVal) {
      if (newVal) {
        this.selectedMembers = []
      }
    }
  },
  methods: {
    toggleMember(username) {
      const idx = this.selectedMembers.indexOf(username)
      if (idx > -1) {
        this.selectedMembers.splice(idx, 1)
      } else {
        this.selectedMembers.push(username)
      }
    },
    isSelected(username) {
      return this.selectedMembers.includes(username)
    },
    closeModal() {
      this.selectedMembers = []
      this.$emit('close')
    },
    async initiateCall() {
      if (this.selectedMembers.length === 0 || !this.chat?.id) return

      try {
        const callData = {
          chatId: this.chat.id,
          initiator: this.currentUser,
          participants: [this.currentUser, ...this.selectedMembers],
          timestamp: new Date().toISOString()
        }

        this.$emit('initiate-call', callData)
        this.closeModal()
      } catch (error) {
        console.error('Error initiating call:', error)
        this.$storex.session.onError('Failed to initiate call')
      }
    }
  }
}
</script>

