import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

export const namespaced = true

export const state = () => ({
  // Active call sessions: { chatId: { chatId, participants, startedAt, duration, status } }
  activeCalls: {},

  // Incoming call notifications: { chatId: { chatId, from, fromName, fromAvatar, timestamp } }
  incomingCalls: {},

  // Call history
  callHistory: [],

  // Current active call chatId
  currentCallChatId: null,
  callStatus: 'idle', // 'idle' | 'ringing' | 'connecting' | 'active' | 'ending'

  // Test mode for UI development
  _testMode: false,
  _testModeTimer: null,
  _dummyUsers: ['alice', 'bob', 'charlie', 'diana', 'eva']
})

export const getters = getterTree(state, {
  // Get all active calls
  allActiveCalls: (state) => Object.values(state.activeCalls),

  // Get current call details
  currentCall: (state) => state.currentCallChatId ? state.activeCalls[state.currentCallChatId] : null,

  // Get all incoming calls
  allIncomingCalls: (state) => Object.values(state.incomingCalls),

  // Check if user is in a call
  isInCall: (state) => state.currentCallChatId !== null && state.callStatus === 'active',

  // Get call history
  recentCallHistory: (state) => state.callHistory.slice(-10),

  // Get active call count
  activeCallCount: (_, getters) => getters.allActiveCalls.length,

  // Get incoming call count
  incomingCallCount: (_, getters) => getters.allIncomingCalls.length
})

export const mutations = mutationTree(state, {
  // Add active call using chatId
  addActiveCall(state, call) {
    state.activeCalls[call.chatId] = {
      chatId: call.chatId,
      initiator: call.initiator,
      participants: call.participants || [call.initiator],
      startedAt: call.startedAt || new Date().getTime(),
      duration: 0,
      status: call.status || 'connecting'
    }
  },

  // Update active call status
  updateCallStatus(state, { chatId, status }) {
    if (state.activeCalls[chatId]) {
      state.activeCalls[chatId].status = status
    }
  },

  // Update call duration
  updateCallDuration(state, { chatId, duration }) {
    if (state.activeCalls[chatId]) {
      state.activeCalls[chatId].duration = duration
    }
  },

  // Add participant to call
  addParticipantToCall(state, { chatId, userId }) {
    if (state.activeCalls[chatId] && !state.activeCalls[chatId].participants.includes(userId)) {
      state.activeCalls[chatId].participants.push(userId)
    }
  },

  // Remove participant from call
  removeParticipantFromCall(state, { chatId, userId }) {
    if (state.activeCalls[chatId]) {
      state.activeCalls[chatId].participants = state.activeCalls[chatId].participants.filter(p => p !== userId)
    }
  },

  // End active call
  endActiveCall(state, chatId) {
    const call = state.activeCalls[chatId]
    if (call) {
      // Move to history
      state.callHistory.push({
        ...call,
        endedAt: new Date().getTime(),
        status: 'ended'
      })
      // Remove from active
      delete state.activeCalls[chatId]
      if (state.currentCallChatId === chatId) {
        state.currentCallChatId = null
        state.callStatus = 'idle'
      }
    }
  },

  // Add incoming call notification
  addIncomingCall(state, incomingCall) {
    state.incomingCalls[incomingCall.chatId] = {
      chatId: incomingCall.chatId,
      from: incomingCall.from,
      fromName: incomingCall.fromName,
      fromAvatar: incomingCall.fromAvatar,
      timestamp: new Date().getTime(),
      status: 'pending'
    }
  },

  // Remove incoming call notification
  removeIncomingCall(state, chatId) {
    delete state.incomingCalls[chatId]
  },

  // Set current call
  setCurrentCall(state, chatId) {
    state.currentCallChatId = chatId
  },

  // Set call status
  setCallStatus(state, status) {
    state.callStatus = status
  },

  // Set test mode timer
  setTestModeTimer(state, timer) {
    state._testModeTimer = timer
  },

  // Set test mode
  setTestMode(state, enabled) {
    state._testMode = enabled
  },

  // Clear all call state
  clearAllCalls(state) {
    state.activeCalls = {}
    state.incomingCalls = {}
    state.currentCallChatId = null
    state.callStatus = 'idle'
    if (state._testModeTimer) {
      clearInterval(state._testModeTimer)
      state._testModeTimer = null
    }
    state._testMode = false
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    /**
     * Initiate a new voice call using chatId
     */
    async initiateCall({ state, commit }, { chatId, targetUserId, targetUserName, targetUserAvatar }) {
      if (!chatId) throw new Error('Chat ID is required to initiate call')

      const currentUser = $storex.users.user

      // Add to active calls
      commit('addActiveCall', {
        chatId,
        initiator: currentUser.username,
        participants: [currentUser.username, targetUserId]
      })

      commit('setCurrentCall', chatId)
      commit('setCallStatus', 'ringing')

      // Emit socket event
      $storex.session.emit({
        event: 'voice-call-initiate',
        data: {
          chatId,
          from: currentUser.username,
          fromName: currentUser.username,
          fromAvatar: currentUser.avatar,
          to: targetUserId,
          timestamp: new Date().getTime()
        }
      })

      // Start test mode if enabled
      if (state._testMode) {
        setTimeout(() => {
          $storex.calls.startCallDuration(chatId)
        }, 1500)
      }

      return chatId
    },

    /**
     * Handle incoming call notification
     */
    handleIncomingCall({ commit }, incomingCall) {
      commit('addIncomingCall', incomingCall)
    },

    /**
     * Accept incoming call
     */
    async acceptCall({ state, commit }, chatId) {
      const incomingCall = state.incomingCalls[chatId]
      if (!incomingCall) return

      const currentUser = $storex.users.user

      // Create active call
      commit('addActiveCall', {
        chatId,
        initiator: incomingCall.from,
        participants: [incomingCall.from, currentUser.username]
      })

      commit('setCurrentCall', chatId)
      commit('setCallStatus', 'connecting')
      commit('removeIncomingCall', chatId)

      // Emit socket event
      $storex.session.emit({
        event: 'voice-call-accept',
        data: {
          chatId,
          acceptedBy: currentUser.username,
          timestamp: new Date().getTime()
        }
      })

      // Start test mode if enabled
      if (state._testMode) {
        setTimeout(() => {
          $storex.calls.startCallDuration(chatId)
        }, 1500)
      }
    },

    /**
     * Reject incoming call
     */
    async rejectCall({ state, commit }, chatId) {
      const incomingCall = state.incomingCalls[chatId]
      if (!incomingCall) return

      const currentUser = $storex.users.user
      commit('removeIncomingCall', chatId)

      // Emit socket event
      $storex.session.emit({
        event: 'voice-call-reject',
        data: {
          chatId,
          rejectedBy: currentUser.username,
          timestamp: new Date().getTime()
        }
      })
    },

    /**
     * End active call
     */
    async endCall({ state, commit }, chatId) {
      const currentUser = $storex.users.user

      commit('endActiveCall', chatId)
      commit('setCallStatus', 'idle')

      // Emit socket event
      $storex.session.emit({
        event: 'voice-call-end',
        data: {
          chatId,
          endedBy: currentUser.username,
          timestamp: new Date().getTime()
        }
      })
    },

    /**
     * Add participant to call
     */
    addParticipant({ state, commit }, { chatId, userId }) {
      commit('addParticipantToCall', { chatId, userId })

      // Notify other participants
      $storex.session.emit({
        event: 'voice-call-participant-added',
        data: {
          chatId,
          userId,
          timestamp: new Date().getTime()
        }
      })
    },

    /**
     * Update call duration
     */
    updateDuration({ commit }, { chatId, duration }) {
      commit('updateCallDuration', { chatId, duration })
    },

    /**
     * Enable test mode for UI development
     */
    enableTestMode({ commit }, enabled = true) {
      commit('setTestMode', enabled)
      if (!enabled) {
        $storex.calls.stopCallDuration()
      }
    },

    /**
     * Start automatic call duration updates (test mode)
     */
    startCallDuration({ state, commit }, chatId) {
      if (!state._testMode || !state.activeCalls[chatId]) return

      const call = state.activeCalls[chatId]
      let phase = 0
      const phases = [
        // Phase 0: Connecting (2 seconds)
        { duration: 2000, action: () => {
          if (call.status !== 'connecting') commit('updateCallStatus', { chatId, status: 'connecting' })
        }},
        // Phase 1: Active (1 second in)
        { duration: 1000, action: () => {
          if (call.status !== 'active') commit('updateCallStatus', { chatId, status: 'active' })
        }},
        // Phase 2: Auto-add participant at 10 seconds
        { duration: 9000, action: () => {
          if (call.participants.length < 3) {
            const randomUser = state._dummyUsers[Math.floor(Math.random() * state._dummyUsers.length)]
            if (!call.participants.includes(randomUser)) {
              commit('addParticipantToCall', { chatId, userId: randomUser })
            }
          }
        }},
        // Phase 3: Auto-end call at 30 seconds
        { duration: 20000, action: () => {
          commit('endActiveCall', chatId)
          commit('setCallStatus', 'idle')
        }}
      ]

      let currentPhase = 0
      let elapsed = 0

      const tickInterval = setInterval(() => {
        if (!state.activeCalls[chatId]) {
          clearInterval(tickInterval)
          return
        }

        elapsed += 1000
        const duration = Math.floor(elapsed / 1000)
        commit('updateCallDuration', { chatId, duration })

        // Execute phase actions
        if (currentPhase < phases.length) {
          if (elapsed >= phases.slice(0, currentPhase + 1).reduce((sum, p) => sum + p.duration, 0)) {
            if (currentPhase < phases.length - 1) {
              phases[currentPhase].action()
              currentPhase++
            } else {
              phases[currentPhase].action()
              clearInterval(tickInterval)
            }
          }
        }
      }, 1000)

      commit('setTestModeTimer', tickInterval)
    },

    /**
     * Stop call duration timer
     */
    stopCallDuration({ state, commit }) {
      if (state._testModeTimer) {
        clearInterval(state._testModeTimer)
        commit('setTestModeTimer', null)
      }
    },

    /**
     * Create a test incoming call for UI development
     */
    createTestIncomingCall({ commit, state }, { chatId, options = {} }) {
      const dummyUsers = ['alice', 'bob', 'charlie', 'diana', 'eva']
      const randomUser = dummyUsers[Math.floor(Math.random() * dummyUsers.length)]

      const incomingCall = {
        chatId,
        from: options.from || randomUser,
        fromName: options.fromName || randomUser.charAt(0).toUpperCase() + randomUser.slice(1),
        fromAvatar: options.fromAvatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${randomUser}`,
        timestamp: new Date().getTime()
      }

      commit('addIncomingCall', incomingCall)

      // Auto-reject after 30 seconds if not answered
      setTimeout(() => {
        if (state.incomingCalls[chatId]) {
          commit('removeIncomingCall', chatId)
        }
      }, 30000)

      return chatId
    },

    /**
     * Clear all calls on logout
     */
    clearCalls({ commit }) {
      commit('clearAllCalls')
    }
  }
)

