export const actions = actionTree(
  { state, getters, mutations },
  {
    /**
     * Initiate a voice/group call using the chat ID as the room identifier.
     * Mock: immediately transitions to active after a short delay.
     */
    async initiateCall({ state, commit }, { chatId, participants }) {
      if (!chatId) throw new Error('Chat ID is required')

      const currentUser = $storex.users.user
      const initiator = currentUser?.username || 'me'
      const allParticipants = [initiator, ...(participants || []).filter(p => p !== initiator)]

      commit('addActiveCall', {
        chatId,
        initiator,
        participants: allParticipants,
        status: 'connecting'
      })
      commit('setCurrentCall', chatId)
      commit('setCallStatus', 'connecting')

      // Emit socket event to other participants
      if (!state._mockMode) {
        $storex.session.emit({
          event: 'voice-call-initiate',
          data: {
            chatId,
            from: initiator,
            fromName: initiator,
            fromAvatar: currentUser?.avatar,
            participants: allParticipants,
            timestamp: new Date().getTime()
          }
        })
      }

      // Mock: simulate connecting → active transition
      if (state._mockMode) {
        setTimeout(() => {
          commit('updateCallStatus', { chatId, status: 'active' })
          commit('setCallStatus', 'active')
          $storex.calls._startMockDurationTimer(chatId)
        }, 1200)
      }

      return chatId
    },

    /**
     * Join an existing call in a chat (for calls already in progress).
     */
    async joinCall({ state, commit }, { chatId }) {
      if (!chatId) throw new Error('Chat ID is required')

      const currentUser = $storex.users.user
      const username = currentUser?.username || 'me'

      // If a call already exists, just join it
      if (state.activeCalls[chatId]) {
        commit('addParticipantToCall', { chatId, userId: username })
      } else {
        commit('addActiveCall', {
          chatId,
          initiator: username,
          participants: [username],
          status: 'connecting'
        })
      }

      commit('setCurrentCall', chatId)
      commit('setCallStatus', 'connecting')

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'voice-call-join',
          data: { chatId, userId: username, timestamp: new Date().getTime() }
        })
      }

      if (state._mockMode) {
        setTimeout(() => {
          commit('updateCallStatus', { chatId, status: 'active' })
          commit('setCallStatus', 'active')
          $storex.calls._startMockDurationTimer(chatId)
        }, 800)
      }
