<script>
export default {
  name: 'GroupCallModal',
  props: {
    show: { type: Boolean, default: false },
    chat: { type: Object, default: null }
  },
  emits: ['close', 'call-started', 'call-left', 'call-ended'],
  data() {
    return {
      selectedMembers: [],
      micEnabled: true
    }
  },
  computed: {
    currentUsername() {
      return this.$storex.users.user?.username || 'me'
    },
    isCallActive() {
      return !!this.activeCall && this.activeCall.status === 'active'
    },
    activeCall() {
      return this.$storex.calls.callForChat(this.chat?.id) || null
    },
    availableMembers() {
      const onlineUsers = this.$storex.users.onlineUsers || {}
      return Object.values(onlineUsers)
        .filter(u => u.username !== this.currentUsername)
        .slice(0, 10)
    }
  },
  watch: {
    show(val) {
      if (val) this.selectedMembers = []
    }
  },
  methods: {
    toggleMember(username) {
      const idx = this.selectedMembers.indexOf(username)
      if (idx > -1) this.selectedMembers.splice(idx, 1)
      else this.selectedMembers.push(username)
    },
    isSelected(username) {
      return this.selectedMembers.includes(username)
    },
    async handleStartCall() {
      try {
        await this.$storex.calls.initiateCall({
          chatId: this.chat.id,
          participants: this.selectedMembers
        })
        this.$emit('call-started', { chatId: this.chat.id, participants: this.selectedMembers })
        this.$emit('close')
      } catch (error) {
        console.error('Failed to start call:', error)
        this.$storex.session.onError('Failed to start call')
      }
    },
    async handleLeaveCall() {
      try {
        await this.$storex.calls.leaveCall({ chatId: this.chat.id })
        this.$emit('call-left', this.chat.id)
        this.$emit('close')
      } catch (error) {
        console.error('Failed to leave call:', error)
      }
    },
    async handleEndCall() {
      try {
        await this.$storex.calls.endCall(this.chat.id)
        this.$emit('call-ended', this.chat.id)
        this.$emit('close')
      } catch (error) {
        console.error('Failed to end call:', error)
      }
    }
  }
}
</script>
