  emits: ['toggle-mute', 'open-settings', 'end-call'],
  computed: {
    isConnecting() {
      return this.call?.status === 'connecting'
    },
    formattedDuration() {
      const secs = this.call?.duration || 0
      const h = Math.floor(secs / 3600)
      const m = Math.floor((secs % 3600) / 60)
      const s = secs % 60
      if (h > 0) {
        return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
      }
      return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
    }
  }
}
