<script>
export default {
  name: 'GroupCallNotification',
  props: {
    call: { type: Object, default: null },
    autoExpireSeconds: { type: Number, default: 30 }
  },
  emits: ['accept', 'reject'],
  data() {
    return {
      timeRemaining: 30,
      expiryTimer: null
    }
  },
  computed: {
    incomingCall() {
      return this.call
    },
    progressPercent() {
      return (this.timeRemaining / this.autoExpireSeconds) * 100
    }
  },
  watch: {
    call(newVal) {
      if (newVal) {
        this.timeRemaining = this.autoExpireSeconds
        this.startTimer()
      } else {
        this.clearTimer()
      }
    }
  },
  beforeUnmount() {
    this.clearTimer()
  },
  methods: {
    startTimer() {
      this.clearTimer()
      this.expiryTimer = setInterval(() => {
        this.timeRemaining--
        if (this.timeRemaining <= 0) {
          this.handleReject()
        }
      }, 1000)
    },
    clearTimer() {
      if (this.expiryTimer) {
        clearInterval(this.expiryTimer)
        this.expiryTimer = null
      }
    },
    handleAccept() {
      this.clearTimer()
      this.$emit('accept', this.incomingCall.chatId)
    },
    handleReject() {
      this.clearTimer()
      this.$emit('reject', this.incomingCall.chatId)
    }
  }
}
</script>

