import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

export const namespaced = true

export const state = () => ({
  // Active call sessions: { chatId: { chatId, participants, startedAt, duration, status } }
  activeCalls: {},

  // Incoming call notifications: { chatId: { chatId, from, fromName, fromAvatar, timestamp } }
  incomingCalls: {},

  // Call history
  callHistory: [],

  // Current active call chatId (the chat this client is actively in)
  currentCallChatId: null,
  callStatus: 'idle', // 'idle' | 'ringing' | 'connecting' | 'active' | 'ending'

  // Mock mode for UI development without real WebRTC/socket
  _mockMode: true,
  _mockDurationTimers: {}
})

export const getters = getterTree(state, {
  allActiveCalls: (state) => Object.values(state.activeCalls),
  currentCall: (state) => state.currentCallChatId ? state.activeCalls[state.currentCallChatId] : null,
  allIncomingCalls: (state) => Object.values(state.incomingCalls),
  isInCall: (state) => state.currentCallChatId !== null && state.callStatus === 'active',
  recentCallHistory: (state) => state.callHistory.slice(-10),
  activeCallCount: (_, getters) => getters.allActiveCalls.length,
  incomingCallCount: (_, getters) => getters.allIncomingCalls.length,

  // Returns the active call for a specific chatId (used by toolbar)
  callForChat: (state) => (chatId) => state.activeCalls[chatId] || null
})

export const mutations = mutationTree(state, {
  addActiveCall(state, call) {
    state.activeCalls = {
      ...state.activeCalls,
      [call.chatId]: {
        chatId: call.chatId,
        initiator: call.initiator,
        participants: call.participants || [call.initiator],
        startedAt: call.startedAt || new Date().getTime(),
        duration: 0,
        status: call.status || 'connecting'
      }
    }
  },

  updateCallStatus(state, { chatId, status }) {
    if (state.activeCalls[chatId]) {
      state.activeCalls = {
        ...state.activeCalls,
        [chatId]: { ...state.activeCalls[chatId], status }
      }
    }
  },

  updateCallDuration(state, { chatId, duration }) {
    if (state.activeCalls[chatId]) {
      state.activeCalls[chatId].duration = duration
    }
  },

  addParticipantToCall(state, { chatId, userId }) {
    if (state.activeCalls[chatId] && !state.activeCalls[chatId].participants.includes(userId)) {
      state.activeCalls[chatId].participants = [...state.activeCalls[chatId].participants, userId]
    }
  },

  removeParticipantFromCall(state, { chatId, userId }) {
    if (state.activeCalls[chatId]) {
      state.activeCalls[chatId].participants = state.activeCalls[chatId].participants.filter(p => p !== userId)
    }
  },

  endActiveCall(state, chatId) {
    const call = state.activeCalls[chatId]
    if (call) {
      state.callHistory = [...state.callHistory, { ...call, endedAt: new Date().getTime(), status: 'ended' }]
      const updated = { ...state.activeCalls }
      delete updated[chatId]
      state.activeCalls = updated
      if (state.currentCallChatId === chatId) {
        state.currentCallChatId = null
        state.callStatus = 'idle'
      }
    }
  },

  addIncomingCall(state, incomingCall) {
    state.incomingCalls = {
      ...state.incomingCalls,
      [incomingCall.chatId]: {
        chatId: incomingCall.chatId,
        from: incomingCall.from,
        fromName: incomingCall.fromName,
        fromAvatar: incomingCall.fromAvatar,
        timestamp: new Date().getTime(),
        status: 'pending'
      }
    }
  },

  removeIncomingCall(state, chatId) {
    const updated = { ...state.incomingCalls }
    delete updated[chatId]
    state.incomingCalls = updated
  },

  setCurrentCall(state, chatId) {
    state.currentCallChatId = chatId
  },

  setCallStatus(state, status) {
    state.callStatus = status
  },

  setMockMode(state, enabled) {
    state._mockMode = enabled
  },

  setMockTimer(state, { chatId, timer }) {
    if (timer === null) {
      const updated = { ...state._mockDurationTimers }
      delete updated[chatId]
      state._mockDurationTimers = updated
    } else {
      state._mockDurationTimers = { ...state._mockDurationTimers, [chatId]: timer }
    }
  },

  clearAllCalls(state) {
    // Clear all mock timers
    Object.values(state._mockDurationTimers).forEach(t => clearInterval(t))
    state.activeCalls = {}
    state.incomingCalls = {}
    state.currentCallChatId = null
    state.callStatus = 'idle'
    state._mockDurationTimers = {}
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    /**
     * Initiate a voice/group call using the chat ID as the room identifier.
     * Mock: immediately transitions to active after a short delay.
     */
    async initiateCall({ state, commit }, { chatId, participants }) {
      if (!chatId) throw new Error('Chat ID is required')

      const currentUser = $storex.users.user
      const initiator = currentUser?.username || 'me'
      const allParticipants = [initiator, ...(participants || []).filter(p => p !== initiator)]

      commit('addActiveCall', {
        chatId,
        initiator,
        participants: allParticipants,
        status: 'connecting'
      })
      commit('setCurrentCall', chatId)
      commit('setCallStatus', 'connecting')

      // Emit socket event to other participants
      if (!state._mockMode) {
        $storex.session.emit({
          event: 'voice-call-initiate',
          data: {
            chatId,
            from: initiator,
            fromName: initiator,
            fromAvatar: currentUser?.avatar,
            participants: allParticipants,
            timestamp: new Date().getTime()
          }
        })
      }

      // Mock: simulate connecting → active transition
      if (state._mockMode) {
        setTimeout(() => {
          commit('updateCallStatus', { chatId, status: 'active' })
          commit('setCallStatus', 'active')
          $storex.calls._startMockDurationTimer(chatId)
        }, 1200)
      }

      return chatId
    },

    /**
     * Join an existing call in a chat (for calls already in progress).
     */
    async joinCall({ state, commit }, { chatId }) {
      if (!chatId) throw new Error('Chat ID is required')

      const currentUser = $storex.users.user
      const username = currentUser?.username || 'me'

      // If a call already exists, just join it
      if (state.activeCalls[chatId]) {
        commit('addParticipantToCall', { chatId, userId: username })
      } else {
        commit('addActiveCall', {
          chatId,
          initiator: username,
          participants: [username],
          status: 'connecting'
        })
      }

      commit('setCurrentCall', chatId)
      commit('setCallStatus', 'connecting')

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'voice-call-join',
          data: { chatId, userId: username, timestamp: new Date().getTime() }
        })
      }

      if (state._mockMode) {
        setTimeout(() => {
          commit('updateCallStatus', { chatId, status: 'active' })
          commit('setCallStatus', 'active')
          $storex.calls._startMockDurationTimer(chatId)
        }, 800)
      }
    },

    /**
     * Leave the current call without ending it for others.
     */
    async leaveCall({ state, commit }, { chatId }) {
      const currentUser = $storex.users.user
      const username = currentUser?.username || 'me'

      commit('removeParticipantFromCall', { chatId, userId: username })

      // If this client was tracking this call, clear it
      if (state.currentCallChatId === chatId) {
        commit('setCurrentCall', null)
        commit('setCallStatus', 'idle')
      }

      // Stop mock timer
      $storex.calls._stopMockDurationTimer(chatId)

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'voice-call-leave',
          data: { chatId, userId: username, timestamp: new Date().getTime() }
        })
      }
    },

    /**
     * End the call entirely for all participants.
     */
    async endCall({ state, commit }, chatId) {
      const currentUser = $storex.users.user

      $storex.calls._stopMockDurationTimer(chatId)
      commit('endActiveCall', chatId)
      commit('setCallStatus', 'idle')

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'voice-call-end',
          data: {
            chatId,
            endedBy: currentUser?.username,
            timestamp: new Date().getTime()
          }
        })
      }
    },

    /**
     * Handle incoming call notification from socket.
     */
    handleIncomingCall({ commit }, incomingCall) {
      commit('addIncomingCall', incomingCall)
    },

    /**
     * Accept an incoming call.
     */
    async acceptCall({ state, commit }, chatId) {
      const incomingCall = state.incomingCalls[chatId]
      if (!incomingCall) return

      const currentUser = $storex.users.user
      const username = currentUser?.username || 'me'

      commit('addActiveCall', {
        chatId,
        initiator: incomingCall.from,
        participants: [incomingCall.from, username],
        status: 'connecting'
      })
      commit('setCurrentCall', chatId)
      commit('setCallStatus', 'connecting')
      commit('removeIncomingCall', chatId)

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'voice-call-accept',
          data: { chatId, acceptedBy: username, timestamp: new Date().getTime() }
        })
      }

      if (state._mockMode) {
        setTimeout(() => {
          commit('updateCallStatus', { chatId, status: 'active' })
          commit('setCallStatus', 'active')
          $storex.calls._startMockDurationTimer(chatId)
        }, 800)
      }
    },

    /**
     * Reject an incoming call.
     */
    async rejectCall({ state, commit }, chatId) {
      const incomingCall = state.incomingCalls[chatId]
      if (!incomingCall) return

      const currentUser = $storex.users.user
      commit('removeIncomingCall', chatId)

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'voice-call-reject',
          data: { chatId, rejectedBy: currentUser?.username, timestamp: new Date().getTime() }
        })
      }
    },

    /**
     * Update call status (used by socket events).
     */
    updateCallStatus({ commit }, { chatId, status }) {
      commit('updateCallStatus', { chatId, status })
    },

    /**
     * Add participant to call (used by socket events).
     */
    addParticipantToCall({ commit }, { chatId, userId }) {
      commit('addParticipantToCall', { chatId, userId })
    },

    /**
     * End active call from socket event.
     */
    endActiveCall({ commit }, chatId) {
      $storex.calls._stopMockDurationTimer(chatId)
      commit('endActiveCall', chatId)
    },

    /**
     * Update call duration manually.
     */
    updateDuration({ commit }, { chatId, duration }) {
      commit('updateCallDuration', { chatId, duration })
    },

    // ─────────────────────────────────────────────────
    // MOCK HELPERS
    // ─────────────────────────────────────────────────

    /**
     * Enable/disable mock mode.
     */
    setMockMode({ commit }, enabled) {
      commit('setMockMode', enabled)
    },

    /**
     * Start the duration ticker for a mock call.
     * Internal helper — prefixed with _ convention.
     */
    _startMockDurationTimer({ state, commit }, chatId) {
      // Avoid duplicate timers
      if (state._mockDurationTimers[chatId]) return

      const timer = setInterval(() => {
        const call = state.activeCalls[chatId]
        if (!call) {
          clearInterval(timer)
          commit('setMockTimer', { chatId, timer: null })
          return
        }
        const duration = Math.floor((Date.now() - call.startedAt) / 1000)
        commit('updateCallDuration', { chatId, duration })
      }, 1000)

      commit('setMockTimer', { chatId, timer })
    },

    /**
     * Stop the duration ticker for a call.
     */
    _stopMockDurationTimer({ state, commit }, chatId) {
      const timer = state._mockDurationTimers[chatId]
      if (timer) {
        clearInterval(timer)
        commit('setMockTimer', { chatId, timer: null })
      }
    },

    /**
     * Simulate an incoming call for testing.
     */
    mockIncomingCall({ commit }, { chatId, fromName }) {
      const names = ['alice', 'bob', 'charlie', 'diana']
      const name = fromName || names[Math.floor(Math.random() * names.length)]

      commit('addIncomingCall', {
        chatId: chatId || `mock_${Date.now()}`,
        from: name,
        fromName: name.charAt(0).toUpperCase() + name.slice(1),
        fromAvatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${name}`,
        timestamp: new Date().getTime()
      })
    },

    /**
     * Clear all calls (e.g. on logout).
     */
    clearCalls({ commit }) {
      commit('clearAllCalls')
    }
  }
)

