import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

export const namespaced = true

export const state = () => ({
  // Active meet sessions: { meetId: { meetId, name, initiator, participants, startedAt, duration, status } }
  activeMeets: {},

  // Incoming meet invitations: { meetId: { meetId, from, fromName, fromAvatar, timestamp } }
  incomingInvitations: {},

  // Meet history
  meetHistory: [],

  // Current active meet ID (the meet this client is actively in)
  currentMeetId: null,
  meetStatus: 'idle', // 'idle' | 'ringing' | 'connecting' | 'active' | 'ending'

  // Mock mode for UI development without real WebRTC/socket
  _mockMode: true,
  _mockDurationTimers: {}
})

export const getters = getterTree(state, {
  allActiveMeets: (state) => Object.values(state.activeMeets),
  currentMeet: (state) => state.currentMeetId ? state.activeMeets[state.currentMeetId] : null,
  allIncomingInvitations: (state) => Object.values(state.incomingInvitations),
  isInMeet: (state) => state.currentMeetId !== null && state.meetStatus === 'active',
  recentMeetHistory: (state) => state.meetHistory.slice(-10),
  activeMeetCount: (_, getters) => getters.allActiveMeets.length,
  incomingInvitationCount: (_, getters) => getters.allIncomingInvitations.length,
  meetForId: (state) => (meetId) => state.activeMeets[meetId] || null
})

export const mutations = mutationTree(state, {
  addActiveMeet(state, meet) {
    state.activeMeets = {
      ...state.activeMeets,
      [meet.meetId]: {
        meetId: meet.meetId,
        name: meet.name || `Meet ${meet.meetId.slice(0, 8)}`,
        initiator: meet.initiator,
        participants: meet.participants || [meet.initiator],
        startedAt: meet.startedAt || new Date().getTime(),
        duration: 0,
        status: meet.status || 'connecting'
      }
    }
  },

  updateMeetStatus(state, { meetId, status }) {
    if (state.activeMeets[meetId]) {
      state.activeMeets = {
        ...state.activeMeets,
        [meetId]: { ...state.activeMeets[meetId], status }
      }
    }
  },

  updateMeetDuration(state, { meetId, duration }) {
    if (state.activeMeets[meetId]) {
      state.activeMeets[meetId].duration = duration
    }
  },

  addParticipantToMeet(state, { meetId, userId }) {
    if (state.activeMeets[meetId] && !state.activeMeets[meetId].participants.includes(userId)) {
      state.activeMeets[meetId].participants = [...state.activeMeets[meetId].participants, userId]
    }
  },

  removeParticipantFromMeet(state, { meetId, userId }) {
    if (state.activeMeets[meetId]) {
      state.activeMeets[meetId].participants = state.activeMeets[meetId].participants.filter(p => p !== userId)
    }
  },

  endActiveMeet(state, meetId) {
    const meet = state.activeMeets[meetId]
    if (meet) {
      state.meetHistory = [...state.meetHistory, { ...meet, endedAt: new Date().getTime(), status: 'ended' }]
      const updated = { ...state.activeMeets }
      delete updated[meetId]
      state.activeMeets = updated
      if (state.currentMeetId === meetId) {
        state.currentMeetId = null
        state.meetStatus = 'idle'
      }
    }
  },

  addIncomingInvitation(state, invitation) {
    state.incomingInvitations = {
      ...state.incomingInvitations,
      [invitation.meetId]: {
        meetId: invitation.meetId,
        from: invitation.from,
        fromName: invitation.fromName,
        fromAvatar: invitation.fromAvatar,
        timestamp: new Date().getTime(),
        status: 'pending'
      }
    }
  },

  removeIncomingInvitation(state, meetId) {
    const updated = { ...state.incomingInvitations }
    delete updated[meetId]
    state.incomingInvitations = updated
  },

  setCurrentMeet(state, meetId) {
    state.currentMeetId = meetId
  },

  setMeetStatus(state, status) {
    state.meetStatus = status
  },

  setMockMode(state, enabled) {
    state._mockMode = enabled
  },

  setMockTimer(state, { meetId, timer }) {
    if (timer === null) {
      const updated = { ...state._mockDurationTimers }
      delete updated[meetId]
      state._mockDurationTimers = updated
    } else {
      state._mockDurationTimers = { ...state._mockDurationTimers, [meetId]: timer }
    }
  },

  clearAllMeets(state) {
    Object.values(state._mockDurationTimers).forEach(t => clearInterval(t))
    state.activeMeets = {}
    state.incomingInvitations = {}
    state.currentMeetId = null
    state.meetStatus = 'idle'
    state._mockDurationTimers = {}
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    /**
     * Initiate a new meet session.
     * Mock: immediately transitions to active after a short delay.
     */
    async initiateMeet({ state, commit }, { meetId, name, participants }) {
      if (!meetId) throw new Error('Meet ID is required')

      const currentUser = $storex.users.user
      const initiator = currentUser?.username || 'me'
      const allParticipants = [initiator, ...(participants || []).filter(p => p !== initiator)]

      commit('addActiveMeet', {
        meetId,
        name,
        initiator,
        participants: allParticipants,
        status: 'connecting'
      })
      commit('setCurrentMeet', meetId)
      commit('setMeetStatus', 'connecting')

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'meet-initiate',
          data: {
            meetId,
            from: initiator,
            fromName: initiator,
            fromAvatar: currentUser?.avatar,
            participants: allParticipants,
            timestamp: new Date().getTime()
          }
        })
      }

      if (state._mockMode) {
        setTimeout(() => {
          commit('updateMeetStatus', { meetId, status: 'active' })
          commit('setMeetStatus', 'active')
          $storex.meets._startMockDurationTimer(meetId)
        }, 1200)
      }

      return meetId
    },

    /**
     * Join an existing meet session.
     */
    async joinMeet({ state, commit }, { meetId }) {
      if (!meetId) throw new Error('Meet ID is required')

      const currentUser = $storex.users.user
      const username = currentUser?.username || 'me'

      if (state.activeMeets[meetId]) {
        commit('addParticipantToMeet', { meetId, userId: username })
      } else {
        commit('addActiveMeet', {
          meetId,
          initiator: username,
          participants: [username],
          status: 'connecting'
        })
      }

      commit('setCurrentMeet', meetId)
      commit('setMeetStatus', 'connecting')

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'meet-join',
          data: { meetId, userId: username, timestamp: new Date().getTime() }
        })
      }

      if (state._mockMode) {
        setTimeout(() => {
          commit('updateMeetStatus', { meetId, status: 'active' })
          commit('setMeetStatus', 'active')
          $storex.meets._startMockDurationTimer(meetId)
        }, 800)
      }
    },

    /**
     * Leave the current meet without ending it for others.
     */
    async leaveMeet({ state, commit }, { meetId }) {
      const currentUser = $storex.users.user
      const username = currentUser?.username || 'me'

      commit('removeParticipantFromMeet', { meetId, userId: username })

      if (state.currentMeetId === meetId) {
        commit('setCurrentMeet', null)
        commit('setMeetStatus', 'idle')
      }

      $storex.meets._stopMockDurationTimer(meetId)

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'meet-leave',
          data: { meetId, userId: username, timestamp: new Date().getTime() }
        })
      }
    },

    /**
     * End the meet entirely for all participants.
     */
    async endMeet({ state, commit }, meetId) {
      const currentUser = $storex.users.user

      $storex.meets._stopMockDurationTimer(meetId)
      commit('endActiveMeet', meetId)
      commit('setMeetStatus', 'idle')

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'meet-end',
          data: {
            meetId,
            endedBy: currentUser?.username,
            timestamp: new Date().getTime()
          }
        })
      }
    },

    /**
     * Handle incoming meet invitation from socket.
     */
    handleIncomingInvitation({ commit }, invitation) {
      commit('addIncomingInvitation', invitation)
    },

    /**
     * Accept a meet invitation.
     */
    async acceptInvitation({ state, commit }, meetId) {
      const invitation = state.incomingInvitations[meetId]
      if (!invitation) return

      const currentUser = $storex.users.user
      const username = currentUser?.username || 'me'

      commit('addActiveMeet', {
        meetId,
        initiator: invitation.from,
        participants: [invitation.from, username],
        status: 'connecting'
      })
      commit('setCurrentMeet', meetId)
      commit('setMeetStatus', 'connecting')
      commit('removeIncomingInvitation', meetId)

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'meet-accept',
          data: { meetId, acceptedBy: username, timestamp: new Date().getTime() }
        })
      }

      if (state._mockMode) {
        setTimeout(() => {
          commit('updateMeetStatus', { meetId, status: 'active' })
          commit('setMeetStatus', 'active')
          $storex.meets._startMockDurationTimer(meetId)
        }, 800)
      }
    },

    /**
     * Reject a meet invitation.
     */
    async rejectInvitation({ state, commit }, meetId) {
      const invitation = state.incomingInvitations[meetId]
      if (!invitation) return

      const currentUser = $storex.users.user
      commit('removeIncomingInvitation', meetId)

      if (!state._mockMode) {
        $storex.session.emit({
          event: 'meet-reject',
          data: { meetId, rejectedBy: currentUser?.username, timestamp: new Date().getTime() }
        })
      }
    },

    /**
     * Update meet status (used by socket events).
     */
    updateMeetStatus({ commit }, { meetId, status }) {
      commit('updateMeetStatus', { meetId, status })
    },

    /**
     * Add participant to meet (used by socket events).
     */
    addParticipantToMeet({ commit }, { meetId, userId }) {
      commit('addParticipantToMeet', { meetId, userId })
    },

    /**
     * End active meet from socket event.
     */
    endActiveMeet({ commit }, meetId) {
      $storex.meets._stopMockDurationTimer(meetId)
      commit('endActiveMeet', meetId)
    },

    /**
     * Update meet duration manually.
     */
    updateDuration({ commit }, { meetId, duration }) {
      commit('updateMeetDuration', { meetId, duration })
    },

    // ─────────────────────────────────────────────────
    // MOCK HELPERS
    // ─────────────────────────────────────────────────

    /**
     * Enable/disable mock mode.
     */
    setMockMode({ commit }, enabled) {
      commit('setMockMode', enabled)
    },

    /**
     * Start the duration ticker for a mock meet.
     */
    _startMockDurationTimer({ state, commit }, meetId) {
      if (state._mockDurationTimers[meetId]) return

      const timer = setInterval(() => {
        const meet = state.activeMeets[meetId]
        if (!meet) {
          clearInterval(timer)
          commit('setMockTimer', { meetId, timer: null })
          return
        }
        const duration = Math.floor((Date.now() - meet.startedAt) / 1000)
        commit('updateMeetDuration', { meetId, duration })
      }, 1000)

      commit('setMockTimer', { meetId, timer })
    },

    /**
     * Stop the duration ticker for a meet.
     */
    _stopMockDurationTimer({ state, commit }, meetId) {
      const timer = state._mockDurationTimers[meetId]
      if (timer) {
        clearInterval(timer)
        commit('setMockTimer', { meetId, timer: null })
      }
    },

    /**
     * Simulate an incoming invitation for testing.
     */
    mockIncomingInvitation({ commit }, { meetId, fromName }) {
      const names = ['alice', 'bob', 'charlie', 'diana']
      const name = fromName || names[Math.floor(Math.random() * names.length)]

      commit('addIncomingInvitation', {
        meetId: meetId || `meet_${Date.now()}`,
        from: name,
        fromName: name.charAt(0).toUpperCase() + name.slice(1),
        fromAvatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${name}`,
        timestamp: new Date().getTime()
      })
    },

    /**
     * Clear all meets (e.g. on logout).
     */
    clearMeets({ commit }) {
      commit('clearAllMeets')
    }
  }
)

import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'
import { API } from '../api/api'
import moment from 'moment'

export const namespaced = true

export const state = () => ({
  showCoder: false,
  showBrowser: false,
  lastActiveTab: "",
  codxJuniorWidth: 30,
  isMobile: false,
  orientation: 'portrait',
  openedFile: null,
  showLogs: false,
  voiceLanguage: 'en-US',
  voiceLanguages: {
    "en-US": "English",
    "es-SP": "Español"
  },
  viewMode: 'expert',
  openApps: {},
  appDivided: 'horizontal',
  resolution: API.screen.display?.resolution,
  resolutions: API.screen.display?.resolutions,
  monitor: "preview",
  monitors: {
    "preview": "CODX-SCREEN-PREVIEW",
    "shared": "CODX-SCREEN-SHARED"
  },
  colorsMap: {},
  coderProjectCodxPath: null,
  uiReady: false,
  floatingCodxJunior: false,
  notifications: [],
  noVNCSettings: {
    resize: 'remote',
  },
  theme: 'dark',
  activeTab: 'home',
  newProject: false,
  activeApp: null,
  appShowMode: null,
  viewEditor: null,
  activeTeam: null,
  teamBarCollapsed: false,
  panelWidths: {
    chat: 30,
    changes: 33,
    preview: 37
  },
  sidebarCollapsed: false,
  projectLoadingState: {
    isLoading: false,
    projectName: '',
    currentStep: null,
    error: null
  }
})

export const getters = getterTree(state, {
  isLandscape: state => state.orientation !== 'portrait',
  monitorToken: state => state.monitors[state.monitor],
  isSharedScreen: () => window.location.pathname === '/shared',
  enableFileManger: () => API.globalSettings?.enable_file_manager,
  activeApps: () => Object.values($storex.ui.openApps),
  isVibeMode: state => state.viewMode === 'vibe',
  isExpertMode: state => state.viewMode === 'expert',
  isDesktopMode: () => $storex.$router.currentRoute.value.name === 'codx-junior-split',
})

export const mutations = mutationTree(state, {
  setActiveTab(state, tab) {
    tab = tab || 'home'
    if (tab !== 'home') {
      $storex.ui.showApp({
        name: tab,
        component: tab
      })
    } else {
      state.activeTab = null
      state.activeApp = null
    }
    $storex.ui.saveState()
  },
  showTab(state, tab) {
    if (tab !== state.activeTab) {
      $storex.ui.setActiveTab(tab)
    }
    if (!state.isMobile) {
      $storex.ui.showApp({
        name: tab,
        component: tab
      })
    }
  },
  closeTab(state) {
    state.activeTab = null
  },
  setCodxJuniorWidth(state, width) {
    state.codxJuniorWidth = width
    $storex.ui.saveState()
  },
  toggleLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.showApp({
      name: 'Logs',
      component: 'log-viewer'
    })
  },
  openChatLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.showApp({
      name: 'Chat logs',
      component: 'chat-logs'
    })
  },
  setVoiceLanguage(state, voiceLanguage) {
    state.voiceLanguage = voiceLanguage
    $storex.ui.saveState()
  },
  setVibeMode(state) {
    state.viewMode = 'vibe'
    $storex.ui.saveState()
  },
  setExpertMode(state) {
    state.viewMode = 'expert'
    $storex.ui.saveState()
  },
  setViewMode(state, mode) {
    state.viewMode = mode
    $storex.ui.saveState()
  },
  setAppDivided(state, divided) {
    state.appDivided = divided
    $storex.ui.saveState()
  },
  setMonitor(state, monitor) {
    state.monitor = monitor
    $storex.ui.saveState()
  },
  setColorsMap(state, colorsMap) {
    state.colorsMap = colorsMap
    $storex.ui.saveState()
  },
  coderOpenPath(state, project) {
    state.coderProjectCodxPath = project.codx_path
  },
  setUIready(state) {
    $storex.ui.loadState()
    state.uiReady = true
  },
  setFloatinCodxJunior(state, floating) {
    state.floatingCodxJunior = floating
    $storex.ui.saveState()
  },
  toggleFloatinCodxJunior(state) {
    state.floatingCodxJunior = !state.floatingCodxJunior
    $storex.ui.saveState()
  },
  addNotification(state, { text, type }) {
    const existing = state.notifications?.find(n => n.text === text)
    if (existing) {
      existing.ts = moment().format("HH:mm:ss")
      return
    }
    const notif = {
      ts: moment().format("HH:mm:ss"),
      text,
      type: type || 'info'
    }
    state.notifications.push(notif)
    setTimeout(() => $storex.ui.removeNotification(notif), 30000)
  },
  removeNotification(state, notification) {
    state.notifications.splice(
      state.notifications.findIndex(n => n === notification), 1)
  },
  clearNotifications(state, notifications) {
    state.notifications = state.notifications.filter(n => !notifications.includes(n))
  },
  setNoVNCSettings(state, settings) {
    state.noVNCSettings = { ...state.noVNCSettings, ...settings }
  },
  setTheme(state, theme) {
    state.theme = theme
  },
  showNewProject(state, show) {
    state.newProject = show
  },
  cloneApp(state, app) {
    $storex.ui.showApp({ ...app, tabId: null })
  },
  resetOpenApps(state) {
    state.openApps = {}
    state.activeApp = null
  },
  showApp(state, app) {
    app.tabId = app.tabId || `${app.key || app.name}-${Date.now()}`
    app.params = app.params || {}
    // Auto-inject project_id if not present
    if (!app.params.project_id && $storex.projects.activeProject?.project_id) {
      app.params.project_id = $storex.projects.activeProject.project_id
    }
    app.initialParams = app.initialParams || JSON.parse(JSON.stringify(app.params))
    app.openedAt = Date.now()

    if (state.viewMode !== 'vibe' && !state.isMobile) {
      // Check if app already exists in openApps state
      const existingApp = Object.values(state.openApps).find(openApp => {
        if (app.key && openApp.key) {
          return openApp.key === app.key
        }
        return openApp.component === app.component && 
              JSON.stringify(openApp.initialParams) === JSON.stringify(app.initialParams)
      })

      if (existingApp) {
        state.activeApp = existingApp
        $storex.views.activatePanel(existingApp.tabId)
        return
      }

      // Check if panel already exists in Desktop API by checking component and initialParams
      const desktopApi = $storex.views._desktopApi
      if (desktopApi && desktopApi.panels) {
        const existingPanel = desktopApi.panels.find(panel => {
          if (app.key && panel.key) {
            return panel.key === app.key
          }
          const panelParams = panel.params?.params || panel.params || {}
          return panel.component === app.component && 
                JSON.stringify(panelParams.initialParams || panelParams) === JSON.stringify(app.initialParams)
        })

        if (existingPanel) {
          state.activeApp = app
          $storex.views.activatePanel(existingPanel.id)
          return
        }
      }
    }

    state.openApps = {
      ...state.openApps,
      [app.tabId]: app
    }
    state.activeApp = app
  },
  updateAppParams(state, { tabId, params }) {
    const app = state.openApps[tabId]
    if (!app) return
    state.openApps = {
      ...state.openApps,
      [tabId]: {
        ...app,
        params: {
          ...app.params,
          ...params
        }
      }
    }
  },
  closeApp(state, app) {
    if (!app) return
    delete state.openApps[app.tabId]
    if (state.activeApp?.tabId === app.tabId) {
      const remainingApps = Object.values(state.openApps)
      if (remainingApps.length > 0) {
        state.activeApp = remainingApps.reduce((latest, current) =>
          current.openedAt > latest.openedAt ? current : latest
        )
      } else {
        state.activeApp = null
      }
    }
    if (!Object.keys(state.openApps).length) {
      if (!state.activeTab) {
        $storex.ui.showTab(state.lastActiveTab || 'tasks')
      }
    }
    $storex.ui.saveState()
  },
  setAppShowMode(state, mode) {
    state.appShowMode = mode
  },
  setSidebarCollapsed(state, collapsed) {
    state.sidebarCollapsed = collapsed
    $storex.ui.saveState()
  },
  openChat(_, chat) {
    if (!$storex.ui.isDesktopMode) {
      $storex.$router.push({
        name: 'chat',
        params: {
          chatId: chat.id,
          chatName: chat.name
        }
      })
    } else {
      $storex.ui.showApp({
        tabId: chat.id,
        name: chat.name,
        component: 'chat',
        params: {
          chat: {
            id: chat.id,
            name: chat.name,
            owner_project_id: chat.owner_project_id
          }
        }
      })
    }
  },
  openFileInViewer(_, filePath) {
    const fileName = filePath.split('/').pop()
    $storex.ui.showApp({
      tabId: `file-viewer-${filePath}`,
      name: fileName,
      component: 'file-viewer',
      params: { filePath }
    })
  },
  openViewEditor(state, view = null) {
    state.viewEditor = { view: view || null }
  },
  closeViewEditor(state) {
    state.viewEditor = null
  },
  setActiveTeam(state, team) {
    state.activeTeam = team
    $storex.ui.saveState()
  },
  setTeamBarCollapsed(state, collapsed) {
    state.teamBarCollapsed = collapsed
    $storex.ui.saveState()
  },
  setPanelWidth(state, { panel, width }) {
    state.panelWidths = {
      ...state.panelWidths,
      [panel]: width
    }
    $storex.ui.saveState()
  },
  setProjectLoadingState(state, loadingState) {
    state.projectLoadingState = {
      ...state.projectLoadingState,
      ...loadingState
    }
  },
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init ({ state }) {
      $storex.ui.handleResize()
      window.addEventListener('resize', () => $storex.ui.handleResize())
      if (API.user?.theme) {
        state.theme = API.user.theme
      }
      state.coderProjectCodxPath = null
    },
    saveState({ state }) {
      if (!state.uiReady) {
        return
      }
      try {
        const data = { 
          ...state, 
          uiReady: false,
          openApps: {},
          viewEditor: null,
          projectLoadingState: {
            isLoading: false,
            projectName: '',
            currentStep: null,
            error: null
          }
        }
        localStorage.setItem('uiState', JSON.stringify(data))
      } catch (error) {
        console.error('Failed to save UI state:', error)
      }
    },
    async loadState({ state }) {
      try {
        const savedState = localStorage.getItem('uiState')
        if (savedState) {
          const parsedState = JSON.parse(savedState)
          Object.keys(parsedState)
            .forEach(k => state[k] = parsedState[k])
        }
      } catch (error) {
        console.error('Failed to parse saved UI state:', error)
      }

      const {
        activeProject: project_id,
        activeChat: chatId
      } = state

      if (project_id && project_id !== $storex.projects.activeProject?.project_id) {
        await $storex.projects.activeProjectChanged({ project_id })
      }
      if (chatId && $storex.projects.activeProject) {
        $storex.projects.setActiveChat({ id: chatId })
      }

      $storex.ui.handleResize()
    },
    handleResize({ state }) {
      const width = window.innerWidth
      const height = window.innerHeight
      const isMobile = width <= 1024
      const orientation = width > height ? 'landscape' : 'portrait'
      state.isMobile = isMobile
      state.orientation = orientation  
    },
    loadTask (_, task) {
      $storex.projects.setActiveChat(task)
    },
    async openFile({ state }, file) {
      if (state.isMobile) {
        state.openedFile = file
      } else {
        await API.coder.openFile(file)
      }
      state.showCoder = true
    },
    async openProjectFile({ state }, file) {
      const { project_path } = $storex.projects.activeProject
      if (!file.startsWith(project_path)) {
        if (!file.startsWith("/") && !project_path.endsWith("/")) {
          file = "/" + file
        }
        file = project_path + file
      }
      await API.coder.openFile(file)
      state.showCoder = true
    },
    setScreenResolution(_, resolution) {
      API.screen.setScreenResolution(resolution)
    },
    async readScreenResolutions ({ state }) {
      await API.screen.getScreenResolution()
      state.resolution = API.screen.display?.resolution
      state.resolutions = API.screen.display?.resolutions
    },
    copyTextToClipboard(_, text) {
      const textArea = document.createElement('textarea')
      textArea.value = text
      document.body.appendChild(textArea)
      textArea.focus()
      textArea.select()
      document.execCommand('copy')
      document.body.removeChild(textArea)
      $storex.ui.addNotification({ text: "Text copied" })
    },
    async readClipboardText(_, itemType = "text/plain") {
      const items = await navigator.clipboard.read()
      const getText = async item => {
        const blob = await item.getType(itemType)
        return await blob.text()
      }
      const allTexts = await Promise.all(
                        items.filter(i => i.types.includes(itemType))
                              .map(i => getText(i)))
      return allTexts.reduce((a, b) => a + b, "")
    },
    async shareScreen() {
      const stream = await navigator.mediaDevices.getDisplayMedia({
        preferCurrentTab: true,
      })
      const [track] = stream.getVideoTracks()
    },
    openNewWindowAppPanel(_, app) {
      const { origin } = window.location
      const url = `${origin}${app.path}`
      window.open(url, app.name)
    },

    openTeamChannel(_, { team, channel }) {
      $storex.ui.showApp({
        tabId: `team-channel-${channel.id}`,
        name: `# ${channel.name}`,
        component: 'team-channel',
        params: { team, channel }
      })
    },

    async openTeamDM(_, { team, member }) {
      const chatId = await $storex.teams.openDirectMessage({ teamId: team.id, member })
      $storex.ui.showApp({
        tabId: `team-dm-${team.id}-${member.id}`,
        name: `@ ${member.username}`,
        component: 'team-dm',
        params: { team, member, chatId }
      })
    },

    openTeamMediaLibrary(_, { team }) {
      $storex.ui.showApp({
        tabId: `team-media-${team.id}`,
        name: `🖼 ${team.name} Media`,
        component: 'team-media-library',
        params: { team }
      })
    },

    openVibeCoding() {
      $storex.ui.showApp({
        key: 'vibe-coding',
        name: 'Vibe Coding',
        component: 'vibe-coding',
        params: {}
      })
    },

    openProjects() {
      $storex.ui.showApp({
        tabId: 'projects',
        name: 'Projects',
        component: 'projects',
        params: {}
      })
    },

    openTeams() {
      $storex.ui.showApp({
        tabId: 'teams',
        name: 'Teams',
        component: 'teams',
        params: {}
      })
    },

    openWorkspaces() {
      $storex.ui.showApp({
        tabId: 'workspaces',
        name: 'Workspaces',
        component: 'workspaces',
        params: {}
      })
    },

    openWorkspace(_, workspace) {
      if (!workspace || !workspace.key) {
        console.warn('[UI] openWorkspace: invalid workspace', workspace)
        return
      }

      const workspaceId = workspace.key
      const workspaceName = workspace.name || `workspace-${workspaceId}`

      if ($storex.ui.isDesktopMode) {
        $storex.ui.showApp({
          tabId: `workspace-${workspaceId}`,
          name: workspaceName,
          component: 'workspace',
          ...workspace
        })
      } else {
        $storex.$router.$navigation.workspaces.open(workspaceId, workspaceName)
      }
    },

    openMeet() {
      if ($storex.ui.isDesktopMode) {
        $storex.ui.showApp({
          tabId: 'meet',
          name: 'Meet',
          component: 'meet',
          params: {}
        })
      } else {
        $storex.$router.push({ name: 'meet' })
      }
    },

    openTasks() {
      $storex.ui.setActiveTab('tasks')
    },

    openWiki() {
      $storex.ui.setActiveTab('wiki')
    },

    openMediaLibrary() {
      $storex.ui.showApp({
        tgabId: 'media-library',
        name: 'Media Library',
        compotabIdnent: 'media-library',
        params: {}
      })
    },

    openHome() {
      $storex.ui.setActiveTab('home')
    },

    openTutorial(_, tutorialId) {
      $storex.ui.showApp({
        tabId: `tutorial-${tutorialId}`,
        name: 'Knowledge',
        component: 'knowledge',
        params: { tutorial: tutorialId }
      })
    },

    setProjectLoading(_, isLoading) {
      $storex.ui.setProjectLoadingState({ isLoading })
    },

    updateProjectLoadingStep(_, { stepId, status, options = {} }) {
      window.dispatchEvent(new CustomEvent('project-loading-step', {
        detail: { stepId, status, options }
      }))
    },

    setProjectLoadingError(_, error) {
      $storex.ui.setProjectLoadingState({ error })
    },
  },
)

import { createRouter, createWebHistory } from 'vue-router'
import { $storex } from '../store'
import Navigate from './navigate'
import QuickChatView from '@/views/QuickChatView.vue'
import WorkspaceView from '@/views/WorkspaceView.vue'
import MessengerView from '@/views/MessengerView.vue'
import MeetView from '@/views/MeetView.vue'
import MetricsDashboard from '@/components/analytics/MetricsDashboard.vue'
import Desktop from '@/components/desktop/Desktop.vue'
import KanbanBoardView from '@/components/kanban/board/KanbanBoardView.vue'
import BrowsersSessionManager from '@/components/browsers/BrowsersSessionManager.vue'

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: [
    {
      // Teams-like launcher home page
      path: '/',
      name: 'home',
      component: QuickChatView
    },
    {
      // Chat routes: router mode
      path: '/chats',
      name: 'chats',
      component: QuickChatView
    },
    {
      path: '/chats/:chatId/:chatName',
      name: 'chat',
      component: QuickChatView
    },
    {
      path: '/chats/:chatId/:chatName/workspace/:workspaceId/:workspaceName',
      name: 'chat-workspace',
      component: QuickChatView
    },
    {
      // Meet routes: router mode
      path: '/meet',
      name: 'meet',
      component: MeetView
    },
    {
      path: '/meet/:meetId',
      name: 'meet-session',
      component: MeetView
    },
    {
      // Workspace routes: router mode
      path: '/workspaces',
      name: 'workspaces',
      component: WorkspaceView
    },
    {
      path: '/workspaces/:workspaceId/:workspaceName',
      name: 'workspace',
      component: WorkspaceView
    },
    {
      // Browser routes: router mode
      path: '/browsers',
      name: 'browsers',
      component: BrowsersSessionManager
    },
    {
      path: '/browsers/:sessionId/:sessionName',
      name: 'browser-session',
      component: BrowsersSessionManager
    },
    {
      path: '/kanban',
      name: 'kanban',
      component: KanbanBoardView
    },
    {
      path: '/messenger',
      name: 'messenger',
      component: MessengerView
    },
    {
      // Desktop / team view (previously the catch-all)
      path: '/desktop/:pathMatch(.*)*',
      name: 'codx-junior-split',
      component: Desktop
    },
    {
      path: '/analytics',
      name: 'analytics',
      component: MetricsDashboard
    },
    {
      // Catch-all: redirect everything else to home
      path: '/:pathMatch(.*)*',
      redirect: '/'
    },
  ]
})

// Initialize navigation API with both $router and $storex
router.$navigation = Navigate({ $router: router, $storex })
router.$navigation.init()

router.beforeEach((to, from) => {
  return router.$navigation.onRouteChanged({ from, to })
})

$storex.$router = router

export default router

export default function Navigate({ $router, $storex }) {

  // ════════════════════════════════════════════════════════════════
  // ROUTE BUILDERS - Centralized route path generation
  // ════════════════════════════════════════════════════════════════

  const routes = {
    chat: {
      list: () => ({ name: 'chats' }),
      open: (chatId, chatName) => ({
        name: 'chat',
        params: { chatId, chatName }
      }),
      openWithWorkspace: (chatId, chatName, workspaceId, workspaceName) => ({
        name: 'chat-workspace',
        params: { chatId, chatName, workspaceId, workspaceName }
      })
    },
    meet: {
      list: () => ({ name: 'meet' }),
      open: (meetId) => ({
        name: 'meet-session',
        params: { meetId }
      })
    },
    workspace: {
      list: () => ({ name: 'workspaces' }),
      open: (workspaceId, workspaceName) => ({
        name: 'workspace',
        params: { workspaceId, workspaceName }
      })
    },
    browser: {
      list: () => ({ name: 'browsers' }),
      open: (sessionId, sessionName) => ({
        name: 'browser-session',
        params: { sessionId, sessionName }
      })
    },
    kanban: {
      open: () => ({ name: 'kanban' })
    },
    messenger: {
      open: () => ({ name: 'messenger' })
    },
    desktop: {
      open: () => ({ name: 'codx-junior-split' })
    },
    mobile: {
      open: () => ({ name: 'mobile' })
    },
    home: {
      open: () => ({ name: 'home' })
    }
  }

  // ════════════════════════════════════════════════════════════════
  // STATE GETTERS
  // ════════════════════════════════════════════════════════════════

  const $navigation = {
    get activeProject() {
      return $storex.projects.activeProject
    },

    get isDesktopMode() {
      return $router.currentRoute.value.name === 'codx-junior-split'
    },

    get isMobileMode() {
      return $router.currentRoute.value.name === 'mobile'
    },

    get isChatView() {
      const name = $router.currentRoute.value.name
      return name === 'chat' || name === 'chat-workspace'
    },

    get isMeetView() {
      const name = $router.currentRoute.value.name
      return name === 'meet' || name === 'meet-session'
    },

    get isWorkspaceView() {
      const name = $router.currentRoute.value.name
      return name === 'workspace' || name === 'workspaces'
    },

    get isBrowserView() {
      const name = $router.currentRoute.value.name
      return name === 'browsers' || name === 'browser-session'
    },

    get isKanbanView() {
      return $router.currentRoute.value.name === 'kanban'
    },

    get isMessengerView() {
      return $router.currentRoute.value.name === 'messenger'
    },

    get isHomeView() {
      return $router.currentRoute.value.name === 'home'
    },

    getCurrentRoute() {
      return $router.currentRoute.value
    },

    getChatId() {
      return $router.currentRoute.value.params.chatId || null
    },

    getChatName() {
      return $router.currentRoute.value.params.chatName || null
    },

    getMeetId() {
      return $router.currentRoute.value.params.meetId || null
    },

    getWorkspaceId() {
      return $router.currentRoute.value.params.workspaceId || null
    },

    getWorkspaceName() {
      return $router.currentRoute.value.params.workspaceName || null
    },

    getSessionId() {
      return $router.currentRoute.value.params.sessionId || null
    },

    getSessionName() {
      return $router.currentRoute.value.params.sessionName || null
    },

    get hasChatContext() {
      return this.getChatId() !== null
    },

    get hasMeetContext() {
      return this.getMeetId() !== null
    },

    get hasWorkspaceContext() {
      return this.getWorkspaceId() !== null
    },

    get hasSessionContext() {
      return this.getSessionId() !== null
    },

    // ════════════════════════════════════════════════════════════════
    // INITIALIZATION
    // ════════════════════════════════════════════════════════════════

    init() {
      // Initialize history state on first load
      if (window.history.length === 1) {
        window.history.replaceState(null, '', '/')
        window.history.pushState(null, '', window.location.href)
      }
    },

    async onRouteChanged({ from, to }) {
      // ── OAuth callback ────────────────────────────────────────────
      if (to.path.startsWith('/auth')) {
        const { code, state } = to.query
        const provider = to.path.split('/').reverse()[0]

        if (!provider || !code) {
          $storex.session.onError('Missing OAuth provider or code')
          return '/'
        }

        try {
          await $storex.users.oauthLogin({ provider, code, state })
          return '/'
        } catch (error) {
          $storex.session.onError('Failed to complete OAuth login')
          return '/'
        }
      }

      // ── Standalone routes with name (opt-out of mobile/desktop redirect) ─
      if (!!to.name) {
        return true
      }

      // ── Mobile redirect ──────────────────────────────────────────
      if ($storex.ui.isMobile && to.name !== 'mobile') {
        return { name: 'mobile', replace: true }
      }

      // ── Desktop: redirect /mobile → home ─────────────────────────
      if (!$storex.ui.isMobile && to.name === 'mobile') {
        return { name: 'home', replace: true }
      }

      return true
    },

    // ════════════════════════════════════════════════════════════════
    // CHAT NAVIGATION
    // ════════════════════════════════════════════════════════════════

    chats: {
      list() {
        $router.push(routes.chat.list())
