          $storex.ui.showApp({
            tabId: 'analytics',
            name: 'Analytics',
            component: 'analytics',
            params: {}
          })
        } else {
          $router.push({ path: '/analytics' })
        }
      }
    },

    // ════════════════════════════════════════════════════════════════
    // WORKSPACE CONTEXT (for reading current state)
    // ════════════════════════════════════════════════════════════════

    workspace: {
      getCurrentWorkspace() {
        const workspaceId = $navigation.getWorkspaceId()
        const workspaceName = $navigation.getWorkspaceName()

        if (workspaceId) {
          return { id: workspaceId, name: workspaceName }
        }
        return null
      },

      hasContext() {
        return $navigation.hasWorkspaceContext
      }
    },

    // ════════════════════════════════════════════════════════════════
    // SESSION CONTEXT (for reading current state)
    // ════════════════════════════════════════════════════════════════

    session: {
      getCurrentSession() {
        const sessionId = $navigation.getSessionId()
        const sessionName = $navigation.getSessionName()

        if (sessionId) {
          return { id: sessionId, name: sessionName }
        }
        return null
      },

      hasContext() {
        return $navigation.hasSessionContext
      }
    }
  }

  return $navigation
}

import { v4 as uuidv4 } from 'uuid';
import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

export const namespaced = true

const EVENT_EXPIRE_SECONDS = 120
setInterval(() => $storex.session.tick(), 1000)

import { API } from '../api/api'

// ── HTTP interceptors ────────────────────────────────────────────────────────
API.interceptors = {
  request: [
    (config) => {
      $storex.session.incApiCalls()
      return config
    },
    (error) => {
      $storex.session.decApiCalls()
      return Promise.reject(error)
    }
  ],
  response: [
    (response) => {
      $storex.session.decApiCalls()
      return response
    },
    (error) => {
      $storex.session.decApiCalls()
      $storex.session.setLastError(error)
      console.error("API ERROR:", error)
      $storex.session.onError(error.toString())
    }
  ]
}

export const state = () => ({
  apiCalls: 0,
  lastError: null,
  id: uuidv4(),
  ts: new Date().getTime(),
  notifications: [],
  connected: false,
  user: {
    userName: new Date().getTime()
  },
  users: null,
  events: []
})

export const getters = getterTree(state, {
  lastEvent: state => state.events[state.events.length - 1]?.data,
  wikiEvents: ({ events }) => events.filter(e => e.data?.type === 'wiki'),
  socket: () => API.socket
})

export const mutations = mutationTree(state, {
  incApiCalls(state) {
    state.apiCalls = state.apiCalls + 1
  },
  decApiCalls(state) {
    state.apiCalls = state.apiCalls - 1
  },
  setLastError(state, error) {
    state.lastError = error
  },
  set$childCodxJuior(state, $childCodxJuior) {
    state.$childCodxJuior = $childCodxJuior
  },
  addNotification(_, notification) {
    $storex.ui.addNotification(notification)
  },
  setConnected(state, connected) {
    state.connected = connected
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init () {
      $storex.session.connect()
    },

    tick ({ state }) {
      const expireNotif = new Date( Date.now() - 1000 * EVENT_EXPIRE_SECONDS ).getTime()
      if (state.events.find(e => e.ts < expireNotif)) {
        state.events = state.events.filter(e => e.ts >= expireNotif)
      }
    },

    connect () {
      if (!API.user) {
        API.disconnectSocket()
        return
      }

      API.initSocket({
        onConnect(socketId) {
          console.log('[session] socket connected', socketId)
          $storex.session.setConnected(true)
          $storex.session.login()
        },
        onDisconnect() {
          console.log('[session] socket disconnected')
          $storex.session.setConnected(false)
        },
        onEvent(payload) {
          $storex.session.onEvent(payload)
        }
      })
    },

    login({ state }) {
      API.socket.emit('codx-junior-login', { user: API.user }, users => {
        state.users = users
      })
    },

    onEvent({ state }, { event, data }) {
      console.log("On server message", event, data)
      state.events.push({ event, data, ts: new Date().getTime() })
      const { codx_path, type, chat } = data
      if (codx_path) {
        data.project = $storex.projects.allProjects?.find(p => p.codx_path === codx_path)
      }
      if (chat) {
        $storex.chats.onChatEvent({ event, data })
      }
      if (type === 'notification') {
        $storex.ui.addNotification(data)
      }
      if (event === 'codx-junior-online-users') {
        $storex.users.setOnlineUsers(data.users)
      }

      // ──── VOICE CALL EVENTS ────────────────────────────────
      if (event === 'voice-call-initiate') {
        // Incoming call notification
        $storex.calls.handleIncomingCall({
          chatId: data.chatId,
          from: data.from,
          fromName: data.fromName,
          fromAvatar: data.fromAvatar,
          timestamp: data.timestamp
        })
        console.log('Incoming call from:', data.from, 'for chat:', data.chatId)
      }

      if (event === 'voice-call-accept') {
        // Call was accepted
        $storex.calls.updateCallStatus({
          chatId: data.chatId,
          status: 'active'
        })
        console.log('Call accepted by:', data.acceptedBy)
      }

      if (event === 'voice-call-reject') {
        // Call was rejected
        $storex.calls.endActiveCall(data.chatId)
        console.log('Call rejected by:', data.rejectedBy)
      }

      if (event === 'voice-call-end') {
        // Call ended
        $storex.calls.endActiveCall(data.chatId)
        console.log('Call ended by:', data.endedBy)
      }

      if (event === 'voice-call-participant-added') {
        // New participant joined
        $storex.calls.addParticipantToCall({
          chatId: data.chatId,
          userId: data.userId
        })
        console.log('Participant joined:', data.userId)
      }

      // ──── MEET EVENTS ────────────────────────────────
      if (event === 'meet-initiate') {
        // Incoming meet invitation
        $storex.meets.handleIncomingInvitation({
          meetId: data.meetId,
          from: data.from,
          fromName: data.fromName,
          fromAvatar: data.fromAvatar,
          timestamp: data.timestamp
        })
        console.log('Incoming meet invitation from:', data.from, 'for meet:', data.meetId)
      }

      if (event === 'meet-accept') {
        // Meet invitation accepted
        $storex.meets.updateMeetStatus({
          meetId: data.meetId,
          status: 'active'
        })
        console.log('Meet accepted by:', data.acceptedBy)
      }

      if (event === 'meet-reject') {
        // Meet invitation rejected
        $storex.meets.endActiveMeet(data.meetId)
        console.log('Meet rejected by:', data.rejectedBy)
      }

      if (event === 'meet-end') {
        // Meet ended
        $storex.meets.endActiveMeet(data.meetId)
        console.log('Meet ended by:', data.endedBy)
      }

      if (event === 'meet-participant-added') {
        // Participant joined meet
        $storex.meets.addParticipantToMeet({
          meetId: data.meetId,
          userId: data.userId
        })
        console.log('Participant joined meet:', data.userId)
      }
    },

    onInfo(_, notification) {
      if (typeof notification === 'string') {
        notification = { text: notification }
      }
      $storex.session.addNotification({ ...notification, type: 'info' })
    },
    onWarning(_, notification) {
      if (typeof notification === 'string') {
        notification = { text: notification }
      }
      $storex.session.addNotification({ ...notification, type: 'warning' })
    },
    onError(_, notification) {
      if (typeof notification === 'string') {
        notification = { text: notification }
      }
      $storex.session.addNotification({ ...notification, type: 'error' })
    },

    emit(_, { event, data }) {
      API.socket?.emit(event, data || {})
    }
  }
)

