          class="flex-1 btn btn-sm btn-error text-white rounded-lg hover:btn-error/90"
        >
          <i class="fas fa-phone-slash"></i>
          Decline
        </button>
        <button
          @click="handleAcceptCall"
          class="flex-1 btn btn-sm btn-success text-white rounded-lg hover:btn-success/90"
        >
          <i class="fas fa-phone"></i>
          Answer
        </button>
      </div>
