      const result = await API.post(`/api/meets/${meetId}/signal/offer`, {
        offer,
        to,
        timestamp: new Date().getTime()
      })
      return result
    } catch (error) {
      console.error('[meets] Failed to send offer:', error)
      throw error
    }
