            <div class="w-20 h-20 rounded-full bg-primary/20 flex items-center justify-center mx-auto">
              <i class="fa-solid fa-video text-4xl text-primary"></i>
            </div>
            <h2 class="text-2xl font-bold">Start a Video Meet</h2>
            <p class="text-base-content/60 max-w-md">
              Create a new meet or join an existing one to connect with your team.
            </p>
          </div>

          <div class="flex gap-3">
            <button @click="startNewMeet" class="btn btn-primary gap-2">
              <i class="fa-solid fa-phone"></i>
              Start Meet
            </button>
            <button @click="showInviteModal = true" class="btn btn-ghost gap-2">
              <i class="fa-solid fa-share"></i>
              Invite Link
            </button>
          </div>

          <!-- Recent meets -->
          <div v-if="recentMeets.length > 0" class="mt-8 w-full max-w-md space-y-2">
            <div class="text-xs font-semibold text-base-content/60 uppercase">Recent</div>
            <button
              v-for="meet in recentMeets"
              :key="meet.meetId"
              @click="joinMeet(meet.meetId)"
              class="w-full flex items-center justify-between p-3 rounded-lg bg-base-200 hover:bg-base-100 transition-colors text-left"
            >
              <div>
                <div class="font-medium text-sm">{{ meet.name }}</div>
                <div class="text-xs text-base-content/50">{{ formatDate(meet.endedAt) }}</div>
              </div>
              <i class="fa-solid fa-arrow-right text-base-content/40"></i>
            </button>
          </div>
        </div>

        <!-- Active meet state -->
        <div v-else class="flex-1 flex flex-col gap-4 p-4">
          <!-- Call Status & Duration -->
          <div class="bg-base-200 rounded-lg p-4 border border-base-content/10">
            <div class="flex items-center justify-between">
              <div>
                <h3 class="font-semibold">{{ currentMeet.name }}</h3>
                <p class="text-sm text-base-content/60">{{ formattedDuration }}</p>
              </div>
              <span class="badge badge-success gap-1">
                <span class="w-1.5 h-1.5 bg-success rounded-full animate-pulse"></span>
                Live
              </span>
            </div>
          </div>

          <!-- Media Controls Panel -->
          <div class="bg-base-200 rounded-lg border border-base-content/10 p-4">
            <div class="flex items-center justify-between mb-4">
              <h3 class="text-sm font-semibold">Media Controls</h3>
              <button
                @click="showCallSettings = true"
                class="btn btn-ghost btn-xs btn-circle"
                title="Call settings"
              >
                <i class="fa-solid fa-sliders"></i>
              </button>
            </div>

            <!-- Control Buttons Grid -->
            <div class="grid grid-cols-3 gap-3">
              <!-- Microphone Toggle -->
              <button
                @click="isMuted = !isMuted"
                :class="isMuted ? 'btn-error' : 'btn-ghost'"
                class="btn btn-lg rounded-xl flex flex-col items-center justify-center gap-2 border border-base-content/20 hover:border-base-content/40 transition-all"
              >
                <i class="fa-solid text-2xl" :class="isMuted ? 'fa-microphone-slash' : 'fa-microphone'"></i>
                <span class="text-xs font-medium">{{ isMuted ? 'Muted' : 'Mic' }}</span>
              </button>

              <!-- Camera Toggle (Disabled) -->
              <button
                class="btn btn-lg rounded-xl flex flex-col items-center justify-center gap-2 border border-base-content/20 opacity-50 cursor-not-allowed"
                title="Camera (coming soon)"
                disabled
              >
                <i class="fa-solid fa-video-slash text-2xl"></i>
                <span class="text-xs font-medium">Camera</span>
              </button>

              <!-- Screen Share (Disabled) -->
              <button
                class="btn btn-lg rounded-xl flex flex-col items-center justify-center gap-2 border border-base-content/20 opacity-50 cursor-not-allowed"
                title="Screen share (coming soon)"
                disabled
              >
                <i class="fa-solid fa-share-from-square text-2xl"></i>
                <span class="text-xs font-medium">Share</span>
              </button>
            </div>
          </div>

          <!-- Participants -->
          <MeetParticipants
            :meet="currentMeet"
            class="flex-1"
          />
        </div>
      </div>

      <!-- Controls -->
      <MeetControls
        v-if="currentMeet"
        :meet="currentMeet"
        :isMuted="isMuted"
        @toggle-mute="onToggleMute"
        @leave="onLeaveMeet"
        @end="onEndMeet"
        @invite="showInviteModal = true"
      />
    </div>

    <!-- Right Panel: Chat (if meet active and has chatId) -->
    <div
      v-if="currentMeet && currentMeet.chatId"
      class="border-l border-base-content/10 bg-base-200 flex flex-col"
      :style="{ width: activeChatCallPanelWidth + '%' }"
    >
      <!-- Chat header with resize handle -->
      <div class="flex items-center justify-between px-4 py-2 border-b border-base-content/10 bg-base-300">
        <h3 class="text-sm font-semibold flex items-center gap-2">
          <i class="fa-solid fa-comments text-primary"></i>
          Meet Chat
        </h3>
        <button @click="toggleChatPanel" class="btn btn-ghost btn-xs btn-circle">
          <i class="fa-solid fa-chevron-right"></i>
        </button>
      </div>

      <!-- Chat View -->
      <div class="flex-1 min-h-0 overflow-hidden">
        <ChatView
          v-if="meetChatData"
          :chat="meetChatData"
          :kanban="null"
          :params="{ params: { chat: meetChatData } }"
        />
      </div>

      <!-- Resize handle -->
      <div
        class="absolute top-0 -left-1 w-1 h-full cursor-col-resize hover:bg-primary/40 transition-colors"
        @mousedown="startResizeChat"
      ></div>
    </div>

    <!-- Settings Sidebar (optional, collapsible) -->
    <div v-if="showSettings" class="w-80 bg-base-200 border-l border-base-content/10 p-4 overflow-y-auto">
      <div class="flex items-center justify-between mb-4">
        <h3 class="font-bold">Settings</h3>
        <button @click="showSettings = false" class="btn btn-ghost btn-xs btn-circle">
          <i class="fa-solid fa-xmark"></i>
        </button>
      </div>

      <!-- Settings content -->
      <div class="space-y-4">
        <div class="space-y-2">
          <label class="text-sm font-semibold">Microphone</label>
          <select class="select select-bordered select-sm w-full">
            <option>Default</option>
            <option>Microphone 1</option>
            <option>Microphone 2</option>
          </select>
        </div>

        <div class="space-y-2">
          <label class="text-sm font-semibold">Speaker</label>
          <select class="select select-bordered select-sm w-full">
            <option>Default</option>
            <option>Speaker 1</option>
            <option>Speaker 2</option>
          </select>
        </div>

        <div class="divider my-3"></div>

        <div class="form-control">
          <label class="label cursor-pointer">
            <span class="label-text text-sm font-semibold">Auto-mute on join</span>
            <input type="checkbox" class="checkbox checkbox-sm" />
          </label>
        </div>

        <div class="form-control">
          <label class="label cursor-pointer">
            <span class="label-text text-sm font-semibold">Show participant names</span>
            <input type="checkbox" class="checkbox checkbox-sm" checked />
          </label>
        </div>
      </div>
    </div>

    <!-- Invite Modal -->
    <MeetInviteModal
      v-if="showInviteModal"
      :meetId="activeMeetId"
      @close="showInviteModal = false"
    />

    <!-- Call Settings Modal -->
    <CallSettingsModal
      v-if="showCallSettings"
      :currentSettings="callSettings"
      @close="showCallSettings = false"
      @save="onSaveCallSettings"
    />
  </div>
</template>

<script>
export default {
  name: 'MeetView',
  components: {
    ChatView
  },
  data() {
    return {
      activeMeetId: null,
      isMuted: false,
      showSettings: false,
      showInviteModal: false,
      showCallSettings: false,
      callSettings: {},
      activeChatCallPanelWidth: 30,
      isResizingChat: false,
      startXChat: 0
    }
  },
  computed: {
    currentMeet() {
      return this.$storex.meets.meetForId(this.activeMeetId)
    },
    recentMeets() {
      return this.$storex.meets.recentMeetHistory.reverse().slice(0, 5)
    },
    formattedDuration() {
      if (!this.currentMeet) return ''
      const secs = this.currentMeet.duration || 0
      const h = Math.floor(secs / 3600)
      const m = Math.floor((secs % 3600) / 60)
      const s = secs % 60
      if (h > 0) {
        return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
      }
      return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
    },
    meetChatData() {
      if (!this.currentMeet || !this.currentMeet.chatId) return null
      const chat = this.$storex.chats.chats[this.currentMeet.chatId]
      return chat || null
    }
  },
  watch: {
    currentMeet: {
      handler(newVal) {
        if (newVal && !this.activeMeetId) {
          this.activeMeetId = newVal.meetId
        }
      },
      immediate: true
    }
  },
  mounted() {
    const meetId = this.$route.params.meetId
    if (meetId) {
      this.activeMeetId = meetId
      this.joinMeet(meetId)
    }
    // Load saved panel width
    const savedWidth = this.$storex.ui.activeChatCallPanelWidth
    if (savedWidth) {
      this.activeChatCallPanelWidth = savedWidth
    }
    document.addEventListener('mousemove', this.onResizeChatMove)
    document.addEventListener('mouseup', this.onResizeChatEnd)
  },
  beforeUnmount() {
    document.removeEventListener('mousemove', this.onResizeChatMove)
    document.removeEventListener('mouseup', this.onResizeChatEnd)
  },
  methods: {
    formatDate(timestamp) {
      if (!timestamp) return ''
      const date = new Date(timestamp)
      return date.toLocaleDateString()
    },
    async startNewMeet() {
      const meetId = `meet_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
      this.activeMeetId = meetId
      try {
        await this.$storex.meets.initiateMeet({
          meetId,
          name: `Meet ${new Date().toLocaleTimeString()}`
        })
        if (this.$router.currentRoute.value.name !== 'meet') {
          this.$router.push({ name: 'meet', params: { meetId } })
        }
      } catch (error) {
        console.error('Failed to start meet:', error)
        this.$storex.session.onError('Failed to start meet')
      }
    },
    async joinMeet(meetId) {
      this.activeMeetId = meetId
      try {
        await this.$storex.meets.joinMeet({ meetId })
        if (this.$router.currentRoute.value.name !== 'meet') {
          this.$router.push({ name: 'meet', params: { meetId } })
        }
      } catch (error) {
        console.error('Failed to join meet:', error)
        this.$storex.session.onError('Failed to join meet')
      }
    },
    async onToggleMute() {
      this.isMuted = !this.isMuted
      if (this.activeMeetId) {
        try {
          await this.$storex.meets.toggleMute({ meetId: this.activeMeetId })
        } catch (error) {
          console.error('Failed to toggle mute:', error)
        }
      }
    },
    async onLeaveMeet() {
      if (!this.activeMeetId) return
      try {
        await this.$storex.meets.leaveMeet({ meetId: this.activeMeetId })
        this.$router.push({ name: 'meet' })
      } catch (error) {
        console.error('Failed to leave meet:', error)
      }
    },
    async onEndMeet() {
      if (!this.activeMeetId) return
      try {
        await this.$storex.meets.endMeet(this.activeMeetId)
        this.$router.push({ name: 'meet' })
      } catch (error) {
        console.error('Failed to end meet:', error)
      }
    },
    onSaveCallSettings(settings) {
      this.callSettings = settings
      console.log('Call settings saved:', settings)
    },
    onClose() {
      this.$router.push({ name: 'home' })
    },
    toggleChatPanel() {
      // Could add collapse/expand logic here
    },
    startResizeChat(e) {
      this.isResizingChat = true
      this.startXChat = e.clientX
    },
    onResizeChatMove: (e) => {
      if (!this.isResizingChat) return
      const delta = e.clientX - this.startXChat
      const container = document.querySelector('[style*="width"]')
      if (container) {
        const newWidth = Math.max(20, Math.min(50, this.activeChatCallPanelWidth - (delta / window.innerWidth) * 100))
        this.activeChatCallPanelWidth = newWidth
      }
    },
    onResizeChatEnd: () => {
      if (this.isResizingChat) {
        this.isResizingChat = false
        this.$storex.ui.setActiveChatCallPanelWidth(this.activeChatCallPanelWidth)
      }
    }
  }
}
</script>
```

